 20 | export function project(x, y, z = 0) {
 21 |   return { x: (x - y) * TILE.x, y: (x + y) * TILE.y - z };
 22 | }
 23 | 
 24 | export function unproject(x, y) {
 25 |   return { x: (x / TILE.x + y / TILE.y) / 2, y: (y / TILE.y - x / TILE.x) / 2 };
 26 | }
