 28 | export function isWalkable(x, y, objects = OBJECTS) {
 29 |   if (!Number.isFinite(x) || !Number.isFinite(y)) return false;
 30 |   const r = FOUNDER_RADIUS;
 31 |   return x >= r && y >= r && x <= ROOM.width - r && y <= ROOM.depth - r &&
 32 |     !objects.some((o) => x > o.x - r && x < o.x + o.w + r && y > o.y - r && y < o.y + o.d + r);
 33 | }
 34 | 
 35 | export function canTravel(from, to, objects = OBJECTS) {
 36 |   const steps = Math.max(1, Math.ceil(Math.hypot(to.x - from.x, to.y - from.y) / 0.07));
 37 |   for (let i = 0; i <= steps; i++) {
 38 |     const t = i / steps;
 39 |     if (!isWalkable(from.x + (to.x - from.x) * t, from.y + (to.y - from.y) * t, objects)) return false;
 40 |   }
 41 |   return true;
 42 | }
