437 | function convexHull(points){
438 |   const sorted=[...points].sort((a,b)=>a.x-b.x||a.y-b.y);
439 |   const cross=(a,b,c)=>(b.x-a.x)*(c.y-a.y)-(b.y-a.y)*(c.x-a.x);
440 |   const lower=[],upper=[];
441 |   for(const p of sorted){while(lower.length>=2&&cross(lower.at(-2),lower.at(-1),p)<=0)lower.pop();lower.push(p);}
442 |   for(const p of [...sorted].reverse()){while(upper.length>=2&&cross(upper.at(-2),upper.at(-1),p)<=0)upper.pop();upper.push(p);}
443 |   lower.pop();upper.pop();return lower.concat(upper);
444 | }
445 | 
446 | function inPolygon(p,points){
447 |   let inside=false;
448 |   for(let i=0,j=points.length-1;i<points.length;j=i++){
449 |     const a=points[i],b=points[j];
450 |     if(((a.y>p.y)!==(b.y>p.y))&&(p.x<(b.x-a.x)*(p.y-a.y)/(b.y-a.y)+a.x))inside=!inside;
451 |   }
452 |   return inside;
453 | }

