export function project(x, y, z = 0) {
  return { x: (x - y) * TILE.x, y: (x + y) * TILE.y - z };
}

export function unproject(x, y) {
  return { x: (x / TILE.x + y / TILE.y) / 2, y: (y / TILE.y - x / TILE.x) / 2 };
}

