polygon(points, fill, stroke = null, width = 1) {
  const ctx = this.ctx;
  ctx.beginPath();
  points.forEach((p, i) => i === 0 ? ctx.moveTo(p.x, p.y) : ctx.lineTo(p.x, p.y));
  ctx.closePath();
  if (fill) { ctx.fillStyle = fill; ctx.fill(); }
  if (stroke) { ctx.strokeStyle = stroke; ctx.lineWidth = width; ctx.stroke(); }
}

plane(x, y, w, d, z, color, stroke = null) {
  this.polygon([project(x, y, z), project(x + w, y, z), project(x + w, y + d, z), project(x, y + d, z)], color, stroke);
}

box(x, y, w, d, z, h, colors, stroke = null) {
  const a = project(x, y, z + h), b = project(x + w, y, z + h);
  const c = project(x + w, y + d, z + h), e = project(x, y + d, z + h);
  this.polygon([e, c, project(x + w, y + d, z), project(x, y + d, z)], colors[0], stroke, .6);
  this.polygon([b, project(x + w, y, z), project(x + w, y + d, z), c], colors[1], stroke, .6);
  this.polygon([a, b, c, e], colors[2], stroke, .6);
}

