  ctx.fillRect(p.x, p.y, w * this.scale, h * this.scale);
  if (stroke) {
    ctx.strokeStyle = stroke;
    ctx.lineWidth = width;
    ctx.strokeRect(p.x, p.y, w * this.scale, h * this.scale);
  }
}

// Simple tile helper for pixel-perfect rendering
tile(x, y, color, border = null) {
  const p = this.screenPoint(x, y);
  const size = TILE_SIZE * this.scale;
  this.ctx.fillStyle = color;
  this.ctx.fillRect(p.x, p.y, size, size);
  if (border) {
    this.ctx.strokeStyle = border;
    this.ctx.lineWidth = Math.max(1, this.scale * 0.5);
    this.ctx.strokeRect(p.x, p.y, size, size);
  }
}

