floor() {
  const ctx = this.ctx;
  ctx.save();

  // Draw checkered floor pattern
  for (let y = 0; y < ROOM.depth; y++) {
    for (let x = 0; x < ROOM.width; x++) {
      const hash = (x + y) % 2;
      const colorIndex = (x * 3 + y * 5) % C.floor.length;
      const color = C.floor[colorIndex];
      const border = hash === 0 ? '#b8a888' : '#c4b394';
      this.tile(x, y, color, border);
    }
