  ctx.lineWidth = Math.max(3, this.scale * 2);
  const p1 = this.screenPoint(0, 0);
  const p2 = this.screenPoint(ROOM.width, ROOM.depth);
  ctx.strokeRect(p1.x, p1.y, (p2.x - p1.x), (p2.y - p1.y));

  ctx.restore();
}

