// Pokemon-style character (16x16 pixel sprite)
character(founder, moving, time, direction) {
  const p = this.screenPoint(founder.x, founder.y);
  const size = TILE_SIZE * this.scale;
  const ctx = this.ctx;

  // Determine facing direction based on movement
  let facing = 'down'; // default
  if (Math.abs(direction.x) > Math.abs(direction.y)) {
    facing = direction.x > 0 ? 'right' : 'left';
  } else if (Math.abs(direction.y) > 0.1) {
    facing = direction.y > 0 ? 'down' : 'up';
  }

  // Simple walking animation
  const walkFrame = moving ? Math.floor(time * 0.008) % 2 : 0;
  const bobOffset = walkFrame * this.scale * 1;

  ctx.save();
  ctx.imageSmoothingEnabled = false; // Pixel-perfect rendering

  // Character sprite (simplified pixel art)
  const spriteSize = size * 0.8;
  const spriteX = p.x + size * 0.1;
  const spriteY = p.y + size * 0.1;

  // Shadow
  ctx.fillStyle = 'rgba(0, 0, 0, 0.3)';
  ctx.fillRect(spriteX + spriteSize * 0.2, spriteY + spriteSize * 0.8, spriteSize * 0.6, spriteSize * 0.15);

  // Body
  ctx.fillStyle = '#e88d6a'; // shirt color
  ctx.fillRect(spriteX + spriteSize * 0.25, spriteY + spriteSize * 0.45, spriteSize * 0.5, spriteSize * 0.35);

  // Head
  ctx.fillStyle = '#f2c9a3'; // skin tone
  ctx.fillRect(spriteX + spriteSize * 0.3, spriteY + spriteSize * 0.2, spriteSize * 0.4, spriteSize * 0.35);

  // Hair
  ctx.fillStyle = '#4a3828';
  ctx.fillRect(spriteX + spriteSize * 0.3, spriteY + spriteSize * 0.15, spriteSize * 0.4, spriteSize * 0.2);

  // Legs (animated when walking)
  ctx.fillStyle = '#5a4a3a';
  if (walkFrame === 0) {
    ctx.fillRect(spriteX + spriteSize * 0.3, spriteY + spriteSize * 0.7, spriteSize * 0.15, spriteSize * 0.2);
    ctx.fillRect(spriteX + spriteSize * 0.55, spriteY + spriteSize * 0.7, spriteSize * 0.15, spriteSize * 0.2);
  } else {
    ctx.fillRect(spriteX + spriteSize * 0.3, spriteY + spriteSize * 0.72, spriteSize * 0.15, spriteSize * 0.18);
    ctx.fillRect(spriteX + spriteSize * 0.55, spriteY + spriteSize * 0.68, spriteSize * 0.15, spriteSize * 0.22);
  }

  // Eyes based on direction
  ctx.fillStyle = '#2a2a2a';
  const eyeSize = this.scale * 1.5;
  if (facing === 'down') {
    ctx.fillRect(spriteX + spriteSize * 0.35, spriteY + spriteSize * 0.35, eyeSize, eyeSize);
    ctx.fillRect(spriteX + spriteSize * 0.55, spriteY + spriteSize * 0.35, eyeSize, eyeSize);
  } else if (facing === 'up') {
    ctx.fillRect(spriteX + spriteSize * 0.35, spriteY + spriteSize * 0.3, eyeSize, eyeSize);
    ctx.fillRect(spriteX + spriteSize * 0.55, spriteY + spriteSize * 0.3, eyeSize, eyeSize);
  } else if (facing === 'left') {
    ctx.fillRect(spriteX + spriteSize * 0.35, spriteY + spriteSize * 0.33, eyeSize, eyeSize);
  } else if (facing === 'right') {
    ctx.fillRect(spriteX + spriteSize * 0.6, spriteY + spriteSize * 0.33, eyeSize, eyeSize);
  }

  ctx.restore();

  // Name label above character
  const labelY = p.y - size * 0.2;
  this.pixelText('ALEX', p.x + size * 0.5, labelY);
}

