 75 |     if (heuristic(current) < step * 1.6 && canTravel(point(current), to, objects)) {
 76 |       const raw = [{ ...to }];
 77 |       let cursor = current;
 78 |       while (cursor) { raw.push(point(cursor)); cursor = cursor.parent; }
 79 |       raw.push({ ...from });
 80 |       raw.reverse();
