 92 |       const x = current.x + dx;
 93 |       const y = current.y + dy;
 94 |       const id = key(x, y);
 95 |       if (closed.has(id)) continue;
 96 |       const p = { x: x * step, y: y * step };
 97 |       if (!canTravel(point(current), p, objects)) continue;
 98 |       const g = current.g + Math.hypot(dx, dy) * step;
