100 |       if (existing && existing.g <= g) continue;
101 |       const node = { x, y, g, f: g + Math.hypot(p.x - to.x, p.y - to.y), parent: current };
102 |       nodes.set(id, node);
103 |       open.push(node);
104 |     }
105 |   }
106 |   return null;
107 | }
