export const ROOM = { width: 16, depth: 12 };
export const TILE_SIZE = 32; // Pokemon-style 32px tiles
export const FOUNDER_RADIUS = 0.4;
export const START = { x: 8, y: 9 };

export const OBJECTS = [
  { id: 'fern', type: 'plant', x: 1, y: 1, w: 1, d: 1, height: 2, label: 'The office optimist', target: { x: 2, y: 1 } },
  { id: 'plan', type: 'board', x: 4, y: 0, w: 4, d: 1, height: 2, label: 'The big-idea board', target: { x: 6, y: 2 } },
  { id: 'cabinet', type: 'cabinet', x: 0, y: 3, w: 2, d: 3, height: 1, label: 'The coffee corner', action: 'coffee', target: { x: 2, y: 4 } },
  { id: 'books', type: 'shelf', x: 0, y: 7, w: 2, d: 2, height: 2, label: 'A little inspiration', target: { x: 2, y: 8 } },
  { id: 'doorplant', type: 'plant', x: 1, y: 10, w: 1, d: 1, height: 2, label: 'Your leafy cofounder', target: { x: 2, y: 10 } },
  { id: 'work', type: 'desk', x: 10, y: 2, w: 3, d: 2, height: 2, label: 'Your workstation', target: { x: 11, y: 5 } },
  { id: 'chair', type: 'chair', x: 11, y: 4, w: 1, d: 1, height: 1, label: 'The founder's seat', action: 'work', target: { x: 11, y: 5 } },
  { id: 'backplant', type: 'plant', x: 14, y: 1, w: 1, d: 1, height: 2, label: 'Chief oxygen officer', target: { x: 14, y: 2 } },
  { id: 'sofa', type: 'sofa', x: 13, y: 6, w: 2, d: 3, height: 1, label: 'The thinking couch', target: { x: 12, y: 8 } },
  { id: 'table', type: 'table', x: 10, y: 7, w: 2, d: 2, height: 1, label: 'A change of perspective', action: 'sofa', target: { x: 10, y: 8 } },
  { id: 'ideas', type: 'desk-small', x: 5, y: 4, w: 3, d: 2, height: 1, label: 'Room for a cofounder', target: { x: 6, y: 6 } },
];

// Top-down orthographic projection (Pokemon-style)
export function project(x, y, z = 0) {
  return { x: x * TILE_SIZE, y: y * TILE_SIZE - z * TILE_SIZE * 0.5 };
}

export function unproject(x, y) {
  return { x: x / TILE_SIZE, y: y / TILE_SIZE };
}

