    this.height = bounds.height;
    const dpr = Math.min(window.devicePixelRatio || 1, 2);
    this.canvas.width = Math.round(bounds.width * dpr);
    this.canvas.height = Math.round(bounds.height * dpr);
    this.dpr = dpr;
    this.updateCamera();
  }

  updateCamera() {
    const roomPixelWidth = ROOM.width * TILE_SIZE;
    const roomPixelHeight = ROOM.depth * TILE_SIZE;
    this.scale = Math.min((this.width - 100) / roomPixelWidth, (this.height - 100) / roomPixelHeight) * this.zoom;
    this.offset = { x: this.width / 2 - (roomPixelWidth / 2) * this.scale, y: this.height / 2 - (roomPixelHeight / 2) * this.scale };
  }

  screenPoint(x, y, z = 0) {
    const p = project(x, y, z);
    return { x: p.x * this.scale + this.offset.x, y: p.y * this.scale + this.offset.y };
  }

  floorPoint(x, y) {
    return unproject((x - this.offset.x) / this.scale, (y - this.offset.y) / this.scale);
