import { OBJECTS, ROOM, TILE_SIZE, project, unproject, isWalkable } from './world.js';

const C = {
  floor: ['#d4c4a0', '#cfc0a0', '#d9ca9f', '#cdb595', '#d2be96'],
  wall: ['#8b7355', '#7a6247', '#9d8568'],
  furniture: ['#6b5d4f', '#7d6f61', '#8a7969'],
  plant: ['#5d8f5d', '#4a7a4a', '#6ea36e'],
  accent: ['#e88d6a', '#f2a68a', '#d87a5a'],
};

export class OfficeRenderer {
  constructor(canvas) {
    this.canvas = canvas;
    this.ctx = canvas.getContext('2d');
    this.width = 0;
    this.height = 0;
    this.zoom = 1;
    this.scale = 1;
    this.offset = { x: 0, y: 0 };
    this.hits = [];
    this.reducedMotion = matchMedia('(prefers-reduced-motion: reduce)').matches;
    this.resize();
  }

  resize() {
    const bounds = this.canvas.getBoundingClientRect();
    this.width = bounds.width;
    this.height = bounds.height;
    const dpr = Math.min(window.devicePixelRatio || 1, 2);
    this.canvas.width = Math.round(bounds.width * dpr);
    this.canvas.height = Math.round(bounds.height * dpr);
    this.dpr = dpr;
    this.updateCamera();
  }

  updateCamera() {
    const roomPixelWidth = ROOM.width * TILE_SIZE;
    const roomPixelHeight = ROOM.depth * TILE_SIZE;
    this.scale = Math.min((this.width - 100) / roomPixelWidth, (this.height - 100) / roomPixelHeight) * this.zoom;
    this.offset = { x: this.width / 2 - (roomPixelWidth / 2) * this.scale, y: this.height / 2 - (roomPixelHeight / 2) * this.scale };
  }

  screenPoint(x, y, z = 0) {
    const p = project(x, y, z);
    return { x: p.x * this.scale + this.offset.x, y: p.y * this.scale + this.offset.y };
  }

  floorPoint(x, y) {
    return unproject((x - this.offset.x) / this.scale, (y - this.offset.y) / this.scale);
  }

  floor() {
    const ctx = this.ctx;
    ctx.save();
    for (let y = 0; y < ROOM.depth; y++) {
      for (let x = 0; x < ROOM.width; x++) {
        const hash = (x + y) % 2;
        const colorIndex = (x * 3 + y * 5) % C.floor.length;
        const color = C.floor[colorIndex];
        const border = hash === 0 ? '#b8a888' : '#c4b394';
        const p = this.screenPoint(x, y);
        const size = TILE_SIZE * this.scale;
        ctx.fillStyle = color;
        ctx.fillRect(p.x, p.y, size, size);
        ctx.strokeStyle = border;
        ctx.lineWidth = Math.max(1, this.scale * 0.5);
        ctx.strokeRect(p.x, p.y, size, size);
      }
    }
    ctx.strokeStyle = C.wall[0];
    ctx.lineWidth = Math.max(3, this.scale * 2);
    const p1 = this.screenPoint(0, 0);
    const p2 = this.screenPoint(ROOM.width, ROOM.depth);
    ctx.strokeRect(p1.x, p1.y, (p2.x - p1.x), (p2.y - p1.y));
    ctx.restore();
  }

  drawObject(obj, time, hovered) {
    const isHovered = hovered === obj;
    this.hits.push(obj);
    const p = this.screenPoint(obj.x, obj.y);
    const w = obj.w * TILE_SIZE * this.scale;
    const h = obj.d * TILE_SIZE * this.scale;
    const ctx = this.ctx;

    if (obj.type === 'plant') {
      const size = TILE_SIZE * this.scale;
      ctx.fillStyle = '#8b6f47';
      ctx.fillRect(p.x + size * 0.2, p.y + size * 0.6, size * 0.6, size * 0.4);
      ctx.fillStyle = isHovered ? '#7db87d' : C.plant[0];
      ctx.fillRect(p.x + size * 0.3, p.y + size * 0.2, size * 0.4, size * 0.5);
      ctx.fillRect(p.x + size * 0.2, p.y + size * 0.3, size * 0.2, size * 0.3);
      ctx.fillRect(p.x + size * 0.6, p.y + size * 0.3, size * 0.2, size * 0.3);
    } else if (obj.type === 'board') {
      ctx.fillStyle = isHovered ? '#f9f3e8' : '#e8dcc8';
      ctx.fillRect(p.x, p.y, w, h);
      ctx.strokeStyle = C.furniture[0];
      ctx.lineWidth = Math.max(2, this.scale * 2);
      ctx.strokeRect(p.x, p.y, w, h);
      ctx.fillStyle = '#d8a87a';
      const noteSize = this.scale * 3;
      ctx.fillRect(p.x + w * 0.2, p.y + h * 0.3, noteSize * 2, noteSize);
      ctx.fillRect(p.x + w * 0.6, p.y + h * 0.5, noteSize * 1.5, noteSize);
    } else if (obj.type === 'cabinet') {
      ctx.fillStyle = isHovered ? '#9d8a6f' : C.furniture[1];
      ctx.fillRect(p.x, p.y, w, h);
      ctx.strokeStyle = '#5a4a3a';
      ctx.lineWidth = Math.max(1, this.scale);
      ctx.strokeRect(p.x, p.y, w / 2, h);
      ctx.strokeRect(p.x + w / 2, p.y, w / 2, h);
      ctx.fillStyle = '#4a3a2a';
      const handleSize = this.scale * 2;
      ctx.fillRect(p.x + w * 0.2, p.y + h * 0.5, handleSize, handleSize);
      ctx.fillRect(p.x + w * 0.7, p.y + h * 0.5, handleSize, handleSize);
    } else if (obj.type === 'shelf') {
      ctx.fillStyle = isHovered ? '#9d8a6f' : C.furniture[2];
      ctx.fillRect(p.x, p.y, w, h);
      ctx.fillStyle = '#5a4a3a';
      const shelfH = h / 3;
      ctx.fillRect(p.x, p.y + shelfH, w, Math.max(1, this.scale));
      ctx.fillRect(p.x, p.y + shelfH * 2, w, Math.max(1, this.scale));
      ctx.fillStyle = '#d87a5a';
      const bookW = this.scale * 2;
      ctx.fillRect(p.x + w * 0.2, p.y + shelfH * 0.3, bookW, shelfH * 0.6);
      ctx.fillRect(p.x + w * 0.5, p.y + shelfH * 0.4, bookW, shelfH * 0.5);
      ctx.fillRect(p.x + w * 0.7, p.y + shelfH * 1.3, bookW, shelfH * 0.5);
    } else if (obj.type === 'desk') {
      ctx.fillStyle = isHovered ? '#a89674' : C.furniture[0];
      ctx.fillRect(p.x, p.y, w, h);
      ctx.strokeStyle = '#5a4a3a';
      ctx.lineWidth = Math.max(2, this.scale * 1.5);
      ctx.strokeRect(p.x, p.y, w, h);
      if (obj.id === 'work') {
        const screenW = w * 0.4;
        const screenH = h * 0.4;
        ctx.fillStyle = '#3a4a5a';
        ctx.fillRect(p.x + w * 0.3, p.y + h * 0.2, screenW, screenH);
        ctx.fillStyle = '#6a8aaa';
        ctx.fillRect(p.x + w * 0.35, p.y + h * 0.25, screenW * 0.8, screenH * 0.7);
      }
    } else if (obj.type === 'desk-small') {
      ctx.fillStyle = isHovered ? '#a89674' : C.furniture[0];
      ctx.fillRect(p.x, p.y, w, h);
      ctx.strokeStyle = '#5a4a3a';
      ctx.lineWidth = Math.max(2, this.scale * 1.5);
      ctx.strokeRect(p.x, p.y, w, h);
    } else if (obj.type === 'chair') {
      const size = TILE_SIZE * this.scale;
      ctx.fillStyle = isHovered ? '#7a6a5a' : '#6a5a4a';
      ctx.fillRect(p.x + size * 0.2, p.y + size * 0.3, size * 0.6, size * 0.5);
      ctx.fillStyle = '#5a4a3a';
      ctx.fillRect(p.x + size * 0.3, p.y + size * 0.1, size * 0.4, size * 0.3);
    } else if (obj.type === 'sofa') {
      ctx.fillStyle = isHovered ? '#b0a890' : C.accent[0];
      ctx.fillRect(p.x, p.y, w, h);
      ctx.fillStyle = '#d8956a';
      const cushionH = h * 0.3;
      ctx.fillRect(p.x + w * 0.1, p.y + h * 0.1, w * 0.8, cushionH);
      ctx.fillStyle = '#c8855a';
      ctx.fillRect(p.x, p.y, w * 0.15, h);
      ctx.fillRect(p.x + w * 0.85, p.y, w * 0.15, h);
    } else if (obj.type === 'table') {
      ctx.fillStyle = isHovered ? '#a89674' : '#988664';
      ctx.fillRect(p.x, p.y, w, h);
      ctx.fillStyle = '#6a5a4a';
      const legSize = this.scale * 2;
      ctx.fillRect(p.x + legSize, p.y + legSize, legSize, legSize);
      ctx.fillRect(p.x + w - legSize * 3, p.y + legSize, legSize, legSize);
      ctx.fillRect(p.x + legSize, p.y + h - legSize * 3, legSize, legSize);
      ctx.fillRect(p.x + w - legSize * 3, p.y + h - legSize * 3, legSize, legSize);
    }
  }

  character(founder, moving, time, direction) {
    const p = this.screenPoint(founder.x, founder.y);
    const size = TILE_SIZE * this.scale;
    const ctx = this.ctx;
    const walkFrame = moving ? Math.floor(time * 0.008) % 2 : 0;
    ctx.save();
    ctx.imageSmoothingEnabled = false;
    const spriteSize = size * 0.8;
    const spriteX = p.x + size * 0.1;
    const spriteY = p.y + size * 0.1;
    ctx.fillStyle = 'rgba(0, 0, 0, 0.3)';
    ctx.fillRect(spriteX + spriteSize * 0.2, spriteY + spriteSize * 0.8, spriteSize * 0.6, spriteSize * 0.15);
    ctx.fillStyle = '#e88d6a';
    ctx.fillRect(spriteX + spriteSize * 0.25, spriteY + spriteSize * 0.45, spriteSize * 0.5, spriteSize * 0.35);
    ctx.fillStyle = '#f2c9a3';
    ctx.fillRect(spriteX + spriteSize * 0.3, spriteY + spriteSize * 0.2, spriteSize * 0.4, spriteSize * 0.35);
    ctx.fillStyle = '#4a3828';
    ctx.fillRect(spriteX + spriteSize * 0.3, spriteY + spriteSize * 0.15, spriteSize * 0.4, spriteSize * 0.2);
    ctx.fillStyle = '#5a4a3a';
    if (walkFrame === 0) {
      ctx.fillRect(spriteX + spriteSize * 0.3, spriteY + spriteSize * 0.7, spriteSize * 0.15, spriteSize * 0.2);
      ctx.fillRect(spriteX + spriteSize * 0.55, spriteY + spriteSize * 0.7, spriteSize * 0.15, spriteSize * 0.2);
    } else {
      ctx.fillRect(spriteX + spriteSize * 0.3, spriteY + spriteSize * 0.72, spriteSize * 0.15, spriteSize * 0.18);
      ctx.fillRect(spriteX + spriteSize * 0.55, spriteY + spriteSize * 0.68, spriteSize * 0.15, spriteSize * 0.22);
    }
    ctx.fillStyle = '#2a2a2a';
    const eyeSize = this.scale * 1.5;
    ctx.fillRect(spriteX + spriteSize * 0.35, spriteY + spriteSize * 0.35, eyeSize, eyeSize);
    ctx.fillRect(spriteX + spriteSize * 0.55, spriteY + spriteSize * 0.35, eyeSize, eyeSize);
    ctx.restore();
    ctx.save();
    ctx.imageSmoothingEnabled = false;
    ctx.fillStyle = '#fff';
    ctx.font = '8px monospace';
    ctx.textAlign = 'center';
    ctx.fillText('ALEX', p.x + size * 0.5, p.y - size * 0.2);
    ctx.restore();
  }

  path(path, founder, time) {
    if (!path.length) return;
    const ctx = this.ctx;
    ctx.save();
    ctx.setLineDash([4, 8]);
    ctx.lineDashOffset = this.reducedMotion ? 0 : -time * .006;
    ctx.beginPath();
    const points = [this.screenPoint(founder.x + 0.5, founder.y + 0.5), ...path.map(p => this.screenPoint(p.x + 0.5, p.y + 0.5))];
    points.forEach((p, i) => i === 0 ? ctx.moveTo(p.x, p.y) : ctx.lineTo(p.x, p.y));
    ctx.strokeStyle = 'rgba(252, 244, 214, 0.7)';
    ctx.lineWidth = Math.max(2, this.scale * 2);
    ctx.stroke();
    ctx.restore();
    const last = path[path.length - 1];
    const destP = this.screenPoint(last.x + 0.5, last.y + 0.5);
    const pulse = this.reducedMotion ? 1 : 1 + Math.sin(time * .006) * .15;
    const markerSize = TILE_SIZE * this.scale * 0.3 * pulse;
    ctx.fillStyle = 'rgba(242, 174, 117, 0.6)';
    ctx.fillRect(destP.x - markerSize / 2, destP.y - markerSize / 2, markerSize, markerSize);
    ctx.strokeStyle = '#fff8e2';
    ctx.lineWidth = Math.max(2, this.scale);
    ctx.strokeRect(destP.x - markerSize / 2, destP.y - markerSize / 2, markerSize, markerSize);
  }

  render({ founder, path, hovered, hoverFloor, direction, moving, time }) {
    const ctx = this.ctx;
    ctx.setTransform(this.dpr, 0, 0, this.dpr, 0, 0);
    ctx.clearRect(0, 0, this.width, this.height);
    ctx.imageSmoothingEnabled = false;
    ctx.save();
    ctx.translate(this.offset.x, this.offset.y);
    ctx.scale(this.scale, this.scale);
    this.floor();
    this.path(path, founder, time);
    if (hoverFloor && !hovered && isWalkable(hoverFloor.x, hoverFloor.y)) {
      const hp = this.screenPoint(Math.floor(hoverFloor.x), Math.floor(hoverFloor.y));
      const tileSize = TILE_SIZE * this.scale;
      ctx.fillStyle = 'rgba(255, 245, 215, 0.2)';
      ctx.fillRect(hp.x, hp.y, tileSize, tileSize);
      ctx.strokeStyle = 'rgba(255, 241, 196, 0.5)';
      ctx.lineWidth = Math.max(2, this.scale);
      ctx.strokeRect(hp.x, hp.y, tileSize, tileSize);
    }
    this.hits = [];
    const entries = OBJECTS.map(o => ({ o, depth: o.y + o.d }));
    entries.push({ player: true, depth: founder.y + 0.5 });
    entries.sort((a, b) => a.depth - b.depth);
    for (const entry of entries) {
      if (entry.player) this.character(founder, moving, time, direction);
      else this.drawObject(entry.o, time, hovered);
    }
    ctx.restore();
  }

  hitTest(sx, sy) {
    const worldX = (sx - this.offset.x) / this.scale / TILE_SIZE;
    const worldY = (sy - this.offset.y) / this.scale / TILE_SIZE;
    for (const o of [...this.hits].reverse()) {
      if (worldX >= o.x && worldX <= o.x + o.w && worldY >= o.y && worldY <= o.y + o.d) return o;
    }
    return null;
  }
}
