433 | function convexHull(points){
434 |   const sorted=[...points].sort((a,b)=>a.x-b.x||a.y-b.y);
435 |   const cross=(a,b,c)=>(b.x-a.x)*(c.y-a.y)-(b.y-a.y)*(c.x-a.x);
436 |   const lower=[],upper=[];
437 |   for(const p of sorted){while(lower.length>=2&&cross(lower.at(-2),lower.at(-1),p)<=0)lower.pop();lower.push(p);}
438 |   for(const p of [...sorted].reverse()){while(upper.length>=2&&cross(upper.at(-2),upper.at(-1),p)<=0)upper.pop();upper.push(p);}
439 |   lower.pop();upper.pop();return lower.concat(upper);
440 | }
