442 | function inPolygon(p,points){
443 |   let inside=false;
444 |   for(let i=0,j=points.length-1;i<points.length;j=i++){
445 |     const a=points[i],b=points[j];
446 |     if(((a.y>p.y)!==(b.y>p.y))&&(p.x<(b.x-a.x)*(p.y-a.y)/(b.y-a.y)+a.x))inside=!inside;
447 |   }
448 |   return inside;
449 | }

