301 | function tick(dt) {
302 |   let moving = false;
303 |   const before = { ...state.founder };
304 |   if (keys.size) {
305 |     const sx = Number(keys.has('d') || keys.has('arrowright')) - Number(keys.has('a') || keys.has('arrowleft'));
306 |     const sy = Number(keys.has('s') || keys.has('arrowdown')) - Number(keys.has('w') || keys.has('arrowup'));
307 |     const dx = sx + sy, dy = sy - sx;
308 |     const length = Math.hypot(dx, dy);
309 |     if (length) {
310 |       direction = { x: dx / length, y: dy / length };
311 |       const candidate = { x: state.founder.x + direction.x * speed * dt, y: state.founder.y + direction.y * speed * dt };
312 |       if (canTravel(state.founder, candidate)) state.founder = candidate;
313 |       else {
314 |         const xOnly = { x: candidate.x, y: state.founder.y };
315 |         const yOnly = { x: state.founder.x, y: candidate.y };
316 |         if(canTravel(state.founder,xOnly))state.founder=xOnly;
317 |         else if(canTravel(state.founder,yOnly))state.founder=yOnly;
318 |       }
319 |     }
320 |   } else if (path.length) {
321 |     let remaining = speed * dt;
322 |     while (path.length && remaining > 0) {
323 |       const target = path[0];
324 |       const dx = target.x - state.founder.x, dy = target.y - state.founder.y;
325 |       const distance = Math.hypot(dx, dy);
326 |       if (distance > .001) direction = { x: dx / distance, y: dy / distance };
327 |       if (distance <= remaining) { state.founder = { ...target };remaining -= distance;path.shift(); }
328 |       else { state.founder.x += direction.x * remaining;state.founder.y += direction.y * remaining;remaining = 0; }
329 |     }
330 |     if (!path.length) {
331 |       const object = pendingInteraction;pendingInteraction = null;save();updateUI();
332 |       if (object) openInteraction(object);
333 |     }
334 |   }
335 |   const distance = Math.hypot(state.founder.x - before.x, state.founder.y - before.y);
336 |   moving = distance > .00001;
337 |   state.distance += distance;
338 |   if (state.distance >= 1.2) complete('walk');
339 |   if (moving) $('#founder-hint').style.opacity = '0';
340 |   clockAccumulator += dt;
341 |   saveAccumulator += dt;
342 |   if (clockAccumulator >= 3) { state.minutes = Math.min(1079, state.minutes + 1);clockAccumulator %= 3;updateUI(); }
343 |   if (saveAccumulator >= 2) { saveAccumulator %= 2;save(); }
344 |   return moving;
