"""

# ─────────────────────────────────────────────
# renderer.js — full top-down pixel-art renderer
# ─────────────────────────────────────────────
JS_RENDERER = r"""import { OBJECTS, ROOM, TILE_SIZE, project, unproject, isWalkable } from './world.js';

// ── Pokemon-style color palette ─────────────────────────────────────────────
const P = {
  // Floor tile checkerboard
  floorA: '#5a7a3a', floorB: '#527035', floorC: '#4e6c32',
  floorAlt: '#527035',
  floorGrid: '#3a5025',
  // Walls (top edge of room)
  wall: '#2a1e0e', wallTop: '#3a2a16', wallLight: '#4a3820',
  wallAccent: '#5a4830',
  // Wood furniture
  wood: '#7a5c38', woodDark: '#5a4228', woodLight: '#9a7a52', woodEdge: '#3a2818',
  // Upholstery / fabric
  fabric: '#7a4a6a', fabricLight: '#9a6a8a', fabricDark: '#5a3050',
  // Tech / screen
  screen: '#1a2a3a', screenGlow: '#3a8ab0', screenLine: '#2a5a7a',
  // Plant
  plantDark: '#2a5a1a', plantMid: '#3a7a28', plantLight: '#5a9a3a',
  plantPot: '#7a5a38', plantSoil: '#3a2818',
  // Whiteboard
  board: '#d8e0c8', boardFrame: '#5a4828', boardMark: '#c87840',
  // Metal / cabinet
  metal: '#5a6a5a', metalDark: '#3a4a3a', metalLight: '#7a8a7a',
  metalHandle: '#9aaa9a',
  // Character
  charSkin: '#d4956a', charHair: '#2a1e10', charShirt: '#3a5a8a',
  charPants: '#2a3a5a', charShoe: '#1a1410', charEye: '#1a1208',
  // Shadow / UI
  shadow: 'rgba(0,0,0,0.35)',
  pathLine: 'rgba(168,240,168,0.75)',
  pathDot: '#78e878',
  hoverTile: 'rgba(168,240,168,0.18)',
  hoverBorder: 'rgba(120,200,120,0.6)',
};

export class OfficeRenderer {
  constructor(canvas) {
    this.canvas = canvas;
    this.ctx = canvas.getContext('2d');
    this.width = 0;
    this.height = 0;
    this.zoom = 1;
    this.scale = 1;
    this.offset = { x: 0, y: 0 };
    this.hits = [];
    this.reducedMotion = matchMedia('(prefers-reduced-motion: reduce)').matches;
    this.resize();
  }

  resize() {
    const bounds = this.canvas.getBoundingClientRect();
    this.width = bounds.width;
    this.height = bounds.height;
    const dpr = Math.min(window.devicePixelRatio || 1, 2);
    this.canvas.width = Math.round(bounds.width * dpr);
    this.canvas.height = Math.round(bounds.height * dpr);
    this.dpr = dpr;
    this.updateCamera();
  }

  updateCamera() {
    const roomW = ROOM.width * TILE_SIZE;
    const roomH = ROOM.depth * TILE_SIZE;
    // Fill as much of the screen as possible while keeping pixel-perfect integer scale
    const rawScale = Math.min(this.width / roomW, this.height / roomH) * this.zoom;
    this.scale = Math.max(1, Math.floor(rawScale));
    this.offset = {
      x: Math.round((this.width  - roomW * this.scale) / 2),
      y: Math.round((this.height - roomH * this.scale) / 2),
    };
  }

  // World tile → screen pixel (top-left of tile)
  screenPoint(tx, ty) {
    const p = project(tx, ty);
    return {
      x: Math.round(p.x * this.scale + this.offset.x),
      y: Math.round(p.y * this.scale + this.offset.y),
    };
  }

  // Screen pixel → world tile coords (floating-point)
  floorPoint(sx, sy) {
    return unproject(
      (sx - this.offset.x) / this.scale,
      (sy - this.offset.y) / this.scale
    );
  }

  // ── px helpers (work in world-pixel space, scaled by this.scale) ───────────
  _r(tx, ty, tw, th, fill, stroke = null, lw = 1) {
    const ctx = this.ctx;
    const p = this.screenPoint(tx, ty);
    const w = Math.round(tw * TILE_SIZE * this.scale);
    const h = Math.round(th * TILE_SIZE * this.scale);
    ctx.fillStyle = fill;
    ctx.fillRect(p.x, p.y, w, h);
    if (stroke) {
      ctx.strokeStyle = stroke;
      ctx.lineWidth = Math.max(1, Math.round(lw * this.scale));
      ctx.strokeRect(p.x + .5, p.y + .5, w - 1, h - 1);
    }
  }

  _line(x1, y1, x2, y2, color, lw = 1) {
    const ctx = this.ctx;
    ctx.strokeStyle = color;
    ctx.lineWidth = Math.max(1, Math.round(lw * this.scale));
    ctx.beginPath();
    ctx.moveTo(x1, y1);
    ctx.lineTo(x2, y2);
    ctx.stroke();
  }

  // ── Floor ──────────────────────────────────────────────────────────────────
  floor() {
    const ctx = this.ctx;
    const S = this.scale;
    const T = TILE_SIZE * S;
    // Checkerboard tiles
    for (let ty = 0; ty < ROOM.depth; ty++) {
      for (let tx = 0; tx < ROOM.width; tx++) {
        const p = this.screenPoint(tx, ty);
        const even = (tx + ty) % 2 === 0;
        ctx.fillStyle = even ? P.floorA : P.floorB;
        ctx.fillRect(p.x, p.y, T, T);
        // subtle inner shadow at top+left edges
        ctx.fillStyle = P.floorGrid;
        ctx.fillRect(p.x, p.y, T, Math.max(1, S));       // top edge
        ctx.fillRect(p.x, p.y, Math.max(1, S), T);       // left edge
      }
    }
    // Room border — thick dark wall outline
    const tl = this.screenPoint(0, 0);
    const W = Math.round(ROOM.width  * TILE_SIZE * S);
    const H = Math.round(ROOM.depth  * TILE_SIZE * S);
    const bw = Math.max(3, S * 2);
    // Top wall (thick, with a lighter strip)
    ctx.fillStyle = P.wall;
    ctx.fillRect(tl.x - bw, tl.y - bw * 2, W + bw * 2, bw * 2);
    ctx.fillStyle = P.wallLight;
    ctx.fillRect(tl.x - bw, tl.y - bw, W + bw * 2, bw);
    // Left wall
    ctx.fillStyle = P.wall;
    ctx.fillRect(tl.x - bw * 2, tl.y - bw * 2, bw * 2, H + bw * 4);
    ctx.fillStyle = P.wallLight;
    ctx.fillRect(tl.x - bw, tl.y - bw, bw, H + bw * 3);
    // Bottom wall (just a border line; player walks through this to exit)
    ctx.fillStyle = P.wallDark || P.wall;
    ctx.fillRect(tl.x - bw, tl.y + H, W + bw * 2, bw * 2);
    // Right wall
    ctx.fillStyle = P.wall;
    ctx.fillRect(tl.x + W, tl.y - bw * 2, bw * 2, H + bw * 4);
  }

  // ── Objects ────────────────────────────────────────────────────────────────
  drawObject(obj, hovered) {
    this.hits.push(obj);
    const hot = hovered === obj;
    const S = this.scale;
    const T = TILE_SIZE * S;
    const p = this.screenPoint(obj.x, obj.y);
    const W = Math.round(obj.w * T);
    const H = Math.round(obj.d * T);
    const ctx = this.ctx;

    // Drop shadow
    ctx.fillStyle = P.shadow;
    ctx.fillRect(p.x + Math.round(S * 2), p.y + Math.round(S * 2), W, H);

    switch (obj.type) {

      case 'plant': {
        // Pot
        const px = p.x + Math.round(T * 0.2), potW = Math.round(T * 0.6);
        const potTop = p.y + Math.round(T * 0.55), potH = Math.round(T * 0.35);
        ctx.fillStyle = P.plantSoil;
        ctx.fillRect(px, potTop, potW, Math.round(S));
        ctx.fillStyle = P.plantPot;
        ctx.fillRect(px, potTop + Math.round(S), potW, potH);
        ctx.fillStyle = P.plantSoil;
        ctx.fillRect(px + Math.round(S), potTop, potW - Math.round(S * 2), Math.round(S));
        // Leaves — layered circles using rects for pixel art
        const lx = p.x + Math.round(T * 0.15), ly = p.y + Math.round(T * 0.05);
        const lw = Math.round(T * 0.7), lh = Math.round(T * 0.55);
        ctx.fillStyle = P.plantDark;
        ctx.fillRect(lx + Math.round(S), ly + Math.round(S), lw - Math.round(S * 2), lh);
        ctx.fillStyle = hot ? P.plantLight : P.plantMid;
        ctx.fillRect(lx, ly + Math.round(lh * 0.2), lw, Math.round(lh * 0.6));
        ctx.fillRect(lx + Math.round(lw * 0.15), ly, Math.round(lw * 0.7), lh);
        ctx.fillStyle = P.plantLight;
        ctx.fillRect(lx + Math.round(lw * 0.3), ly + Math.round(S), Math.round(lw * 0.15), Math.round(S));
        break;
      }

      case 'board': {
        // Frame
        const fw = Math.round(S * 2);
        ctx.fillStyle = P.boardFrame;
        ctx.fillRect(p.x, p.y, W, H);
        // Board surface
        ctx.fillStyle = hot ? '#e8ead8' : P.board;
        ctx.fillRect(p.x + fw, p.y + fw, W - fw * 2, H - fw * 2);
        // Sticky notes / writing marks
        const noteColors = ['#e8c840', '#e84040', '#40b8e8'];
        for (let i = 0; i < 3; i++) {
          const nx = p.x + fw + Math.round((W - fw*2) * (0.1 + i * 0.3));
          const ny = p.y + fw + Math.round((H - fw*2) * 0.2);
          const ns = Math.round(S * 4);
          ctx.fillStyle = noteColors[i];
          ctx.fillRect(nx, ny, ns, ns);
        }
        // Lines on board
        ctx.fillStyle = '#a8b898';
        for (let l = 0; l < 2; l++) {
          const ly2 = p.y + fw + Math.round((H - fw*2) * (0.55 + l * 0.25));
          ctx.fillRect(p.x + fw + Math.round(S), ly2, W - fw*2 - Math.round(S*2), Math.max(1, Math.round(S)));
        }
        break;
      }

      case 'cabinet': {
        // Body
        ctx.fillStyle = hot ? P.metalLight : P.metal;
        ctx.fillRect(p.x, p.y, W, H);
        // Door dividers
        const doors = obj.d >= 2 ? 2 : 1;
        const doorH = Math.round(H / doors);
        ctx.fillStyle = P.metalDark;
        for (let d = 0; d < doors; d++) {
          const dy = p.y + d * doorH;
          if (d > 0) ctx.fillRect(p.x, dy, W, Math.max(1, Math.round(S)));
          // Handle
          const hx = p.x + Math.round(W * 0.42), hy = dy + Math.round(doorH * 0.45);
          const hs = Math.round(S * 2);
          ctx.fillStyle = P.metalHandle;
          ctx.fillRect(hx, hy, hs, Math.round(S * 1.5));
          ctx.fillStyle = P.metalDark;
        }
        // Outline
        ctx.strokeStyle = P.metalDark;
        ctx.lineWidth = Math.max(1, Math.round(S));
        ctx.strokeRect(p.x + .5, p.y + .5, W - 1, H - 1);
        break;
      }

      case 'shelf': {
        // Back panel
        ctx.fillStyle = P.woodDark;
        ctx.fillRect(p.x, p.y, W, H);
        // Shelves
        const shelves = 3;
        const shelfH = Math.round(H / shelves);
        ctx.fillStyle = P.wood;
        for (let s = 0; s < shelves; s++) {
          const sy2 = p.y + s * shelfH;
          ctx.fillRect(p.x, sy2, W, Math.max(2, Math.round(S * 1.5)));
          // Books on shelf
          const bookColors = ['#d05030','#4878b8','#e8a030','#5ab048','#9848a8'];
          const bCount = Math.floor(obj.w * 3);
          const bw2 = Math.round((W - Math.round(S)) / bCount);
          for (let b = 0; b < bCount; b++) {
            ctx.fillStyle = hot ? bookColors[(b + s) % bookColors.length] : bookColors[(b + s * 2) % bookColors.length];
            const bh = Math.round(shelfH * (0.55 + ((b * 7 + s * 3) % 4) * 0.1));
            ctx.fillRect(
              p.x + Math.round(S * 0.5) + b * bw2,
              sy2 + Math.round(S * 1.5),
              bw2 - Math.max(1, Math.round(S * 0.5)),
              bh
            );
          }
        }
        break;
      }

      case 'desk': {
        // Desk surface
        ctx.fillStyle = P.woodEdge;
        ctx.fillRect(p.x, p.y, W, H);
        ctx.fillStyle = hot ? P.woodLight : P.wood;
        const edge = Math.round(S * 1.5);
        ctx.fillRect(p.x + edge, p.y + edge, W - edge*2, H - edge*2);
        // Monitor
        const mw = Math.round(W * 0.38), mh = Math.round(H * 0.5);
        const mx = p.x + Math.round(W * 0.35), my = p.y + Math.round(H * 0.15);
        ctx.fillStyle = P.screen;
        ctx.fillRect(mx, my, mw, mh);
        ctx.fillStyle = P.screenGlow;
        ctx.fillRect(mx + Math.round(S), my + Math.round(S), mw - Math.round(S*2), mh - Math.round(S*2));
        // Screen line scanlines
        ctx.fillStyle = P.screenLine;
        for (let sl = 0; sl < 3; sl++) {
          ctx.fillRect(mx + Math.round(S), my + Math.round(S*2) + sl * Math.round(S*2), mw - Math.round(S*2), Math.max(1, Math.round(S)));
        }
        // Keyboard
        const kw = Math.round(W * 0.35), ky = my + mh + Math.round(S * 2);
        ctx.fillStyle = P.metalDark;
        ctx.fillRect(p.x + Math.round(W*0.33), ky, kw, Math.round(S * 2));
        break;
      }

      case 'desk-small': {
        ctx.fillStyle = P.woodEdge;
        ctx.fillRect(p.x, p.y, W, H);
        ctx.fillStyle = hot ? P.woodLight : P.wood;
        const e = Math.round(S * 1.5);
        ctx.fillRect(p.x + e, p.y + e, W - e*2, H - e*2);
        // A notebook on the desk
        const nw = Math.round(W*0.35), nh = Math.round(H*0.45);
        const nx2 = p.x + Math.round(W*0.2), ny2 = p.y + Math.round(H*0.2);
        ctx.fillStyle = '#e8e0c8';
        ctx.fillRect(nx2, ny2, nw, nh);
        ctx.fillStyle = '#c8c0a8';
        ctx.fillRect(nx2, ny2, Math.round(S), nh);
        break;
      }

      case 'chair': {
        const seat = Math.round(T * 0.5), seatOff = Math.round(T * 0.25);
        // Back rest
        ctx.fillStyle = hot ? P.fabricLight : P.fabric;
        ctx.fillRect(p.x + seatOff, p.y + Math.round(T * 0.05), seat, Math.round(T * 0.35));
        // Seat
        ctx.fillStyle = hot ? P.fabricLight : P.fabric;
        ctx.fillRect(p.x + seatOff, p.y + Math.round(T * 0.38), seat, Math.round(T * 0.35));
        // Legs (4 dots at corners)
        ctx.fillStyle = P.metalDark;
        const ls = Math.round(S * 1.5);
        ctx.fillRect(p.x + seatOff, p.y + Math.round(T*0.72), ls, ls);
        ctx.fillRect(p.x + seatOff + seat - ls, p.y + Math.round(T*0.72), ls, ls);
        break;
      }

      case 'sofa': {
        // Base
        ctx.fillStyle = P.fabricDark;
        ctx.fillRect(p.x, p.y, W, H);
        // Seat cushions
        const cushW = Math.round(W * 0.42);
        ctx.fillStyle = hot ? P.fabricLight : P.fabric;
        ctx.fillRect(p.x + Math.round(S), p.y + Math.round(H*0.25), cushW, Math.round(H*0.6));
        ctx.fillRect(p.x + Math.round(W*0.52), p.y + Math.round(H*0.25), cushW, Math.round(H*0.6));
        // Back
        ctx.fillStyle = P.fabric;
        ctx.fillRect(p.x, p.y, W, Math.round(H*0.28));
        // Arms
        ctx.fillStyle = P.fabricDark;
        ctx.fillRect(p.x, p.y, Math.round(W*0.1), H);
        ctx.fillRect(p.x + W - Math.round(W*0.1), p.y, Math.round(W*0.1), H);
        break;
      }

      case 'table': {
        // Table top
        ctx.fillStyle = P.woodEdge;
        ctx.fillRect(p.x, p.y, W, H);
        ctx.fillStyle = hot ? P.woodLight : P.wood;
        const te = Math.round(S * 2);
        ctx.fillRect(p.x + te, p.y + te, W - te*2, H - te*2);
        // Coffee cups / items on table
        const cup = Math.round(S * 2.5);
        ctx.fillStyle = '#e8e0c8';
        ctx.fillRect(p.x + Math.round(W*0.2), p.y + Math.round(H*0.3), cup, cup);
        ctx.fillRect(p.x + Math.round(W*0.6), p.y + Math.round(H*0.3), cup, cup);
        break;
      }

      default: {
        // Fallback — draw a simple colored box
        this._r(obj.x, obj.y, obj.w, obj.d, hot ? '#8a7a6a' : '#6a5a4a', '#3a2a1a', 1);
      }
    }
  }

  // ── Character (Pokemon-style top-down sprite) ──────────────────────────────
  character(founder, moving, time) {
    const S = this.scale;
    const T = TILE_SIZE * S;
    // Center of the tile the player is on
    const p = this.screenPoint(founder.x, founder.y);
    const cx = p.x + Math.round(T * 0.5);
    const cy = p.y + Math.round(T * 0.5);
    const ctx = this.ctx;

    // Walk cycle: feet alternate
    const frame = (moving && !this.reducedMotion) ? Math.floor(time / 150) % 2 : 0;

    // Shadow
    ctx.fillStyle = 'rgba(0,0,0,0.3)';
    ctx.beginPath();
    ctx.ellipse(cx, cy + Math.round(T * 0.28), Math.round(T*0.22), Math.round(T*0.08), 0, 0, Math.PI*2);
    ctx.fill();

    const u = Math.round(S);   // 1 "pixel" in screen units

    // Feet / shoes
    ctx.fillStyle = P.charShoe;
    if (frame === 0) {
      ctx.fillRect(cx - u*3, cy + u*5, u*2, u*3);
      ctx.fillRect(cx + u*1, cy + u*5, u*2, u*3);
    } else {
      ctx.fillRect(cx - u*3, cy + u*6, u*2, u*2);
      ctx.fillRect(cx + u*1, cy + u*4, u*2, u*4);
    }
    // Legs / pants
    ctx.fillStyle = P.charPants;
    ctx.fillRect(cx - u*3, cy + u*1, u*2, u*5);
    ctx.fillRect(cx + u*1, cy + u*1, u*2, u*5);
    // Body / shirt
    ctx.fillStyle = P.charShirt;
    ctx.fillRect(cx - u*4, cy - u*5, u*8, u*7);
    // Arms
    if (frame === 0) {
      ctx.fillRect(cx - u*6, cy - u*4, u*2, u*5);
      ctx.fillRect(cx + u*4, cy - u*4, u*2, u*5);
    } else {
      ctx.fillRect(cx - u*6, cy - u*5, u*2, u*5);
      ctx.fillRect(cx + u*4, cy - u*3, u*2, u*5);
    }
    // Neck
    ctx.fillStyle = P.charSkin;
    ctx.fillRect(cx - u*1, cy - u*6, u*2, u*2);
    // Head
    ctx.fillStyle = P.charSkin;
    ctx.fillRect(cx - u*4, cy - u*13, u*8, u*8);
    // Hair
    ctx.fillStyle = P.charHair;
    ctx.fillRect(cx - u*4, cy - u*13, u*8, u*3);
    ctx.fillRect(cx - u*4, cy - u*10, u*2, u*2);
    // Eyes
    ctx.fillStyle = P.charEye;
    ctx.fillRect(cx - u*3, cy - u*9, u*2, u*2);
    ctx.fillRect(cx + u*1, cy - u*9, u*2, u*2);
    // Highlight on eyes
    ctx.fillStyle = '#ffffff';
    ctx.fillRect(cx - u*2, cy - u*9, u, u);
    ctx.fillRect(cx + u*2, cy - u*9, u, u);

    // Name tag above head
    ctx.save();
    ctx.font = `bold ${Math.max(7, S * 5)}px 'Courier New', monospace`;
    ctx.textAlign = 'center';
    ctx.fillStyle = 'rgba(0,0,0,0.5)';
    ctx.fillText('ALEX', cx + u, cy - Math.round(T*0.7) + u);
    ctx.fillStyle = '#a8f0a8';
    ctx.fillText('ALEX', cx, cy - Math.round(T*0.7));
    ctx.restore();
  }

  // ── Path ───────────────────────────────────────────────────────────────────
  path(pathArr, founder, time) {
    if (!pathArr.length) return;
    const ctx = this.ctx;
    const S = this.scale;
    const T = TILE_SIZE * S;

    ctx.save();
    ctx.setLineDash([Math.round(S*3), Math.round(S*4)]);
    ctx.lineDashOffset = this.reducedMotion ? 0 : -(time / 80);
    ctx.strokeStyle = P.pathLine;
    ctx.lineWidth = Math.max(1, Math.round(S * 1.5));
    ctx.beginPath();
    const sp = this.screenPoint(founder.x, founder.y);
    ctx.moveTo(sp.x + Math.round(T/2), sp.y + Math.round(T/2));
    for (const wp of pathArr) {
      const pp = this.screenPoint(wp.x, wp.y);
      ctx.lineTo(pp.x + Math.round(T/2), pp.y + Math.round(T/2));
    }
    ctx.stroke();
    ctx.restore();

    // Destination marker — blinking X
    const last = pathArr[pathArr.length - 1];
    const lp = this.screenPoint(Math.floor(last.x), Math.floor(last.y));
    const pulse = this.reducedMotion ? 1 : 0.6 + Math.sin(time / 180) * 0.4;
    ctx.fillStyle = `rgba(120,232,120,${pulse})`;
    const ms = Math.round(T * 0.3);
    const mx = lp.x + Math.round(T/2) - Math.round(ms/2);
    const my = lp.y + Math.round(T/2) - Math.round(ms/2);
    ctx.fillRect(mx, my, ms, ms);
    ctx.fillStyle = 'rgba(20,40,20,0.5)';
    ctx.fillRect(mx + Math.round(S), my + Math.round(S), ms - Math.round(S*2), ms - Math.round(S*2));
  }

  // ── Main render ────────────────────────────────────────────────────────────
  render({ founder, path, hovered, hoverFloor, moving, time }) {
    const ctx = this.ctx;
    ctx.imageSmoothingEnabled = false;
    ctx.setTransform(this.dpr, 0, 0, this.dpr, 0, 0);

    // Clear with dark background
    ctx.fillStyle = '#0a0a0f';
    ctx.fillRect(0, 0, this.width, this.height);

    this.floor();
    this.path(path, founder, time);

    // Hover tile highlight
    if (hoverFloor && !hovered && isWalkable(hoverFloor.x, hoverFloor.y)) {
      const hp = this.screenPoint(Math.floor(hoverFloor.x), Math.floor(hoverFloor.y));
      const T = TILE_SIZE * this.scale;
      ctx.fillStyle = P.hoverTile;
      ctx.fillRect(hp.x, hp.y, T, T);
      ctx.strokeStyle = P.hoverBorder;
      ctx.lineWidth = Math.max(1, Math.round(this.scale));
      ctx.strokeRect(hp.x + .5, hp.y + .5, T - 1, T - 1);
    }

    // Sort objects + player by Y depth (painter's algorithm)
    this.hits = [];
    const entries = OBJECTS.map(o => ({ o, depth: o.y + o.d }));
    entries.push({ player: true, depth: founder.y + 1 });
    entries.sort((a, b) => a.depth - b.depth);

    for (const entry of entries) {
      if (entry.player) this.character(founder, moving, time);
      else this.drawObject(entry.o, hovered);
    }
  }

  // ── Hit test ───────────────────────────────────────────────────────────────
  hitTest(sx, sy) {
    const wp = this.floorPoint(sx, sy);
    for (const o of [...this.hits].reverse()) {
      if (wp.x >= o.x && wp.x < o.x + o.w && wp.y >= o.y && wp.y < o.y + o.d) return o;
    }
    return null;
  }
}
"""

# ─────────────────────────────────────────────
# Write files
# ─────────────────────────────────────────────
files = {
    os.path.join(BASE, 'index.html'):          HTML,
    os.path.join(BASE, 'styles.css'):           CSS,
    os.path.join(BASE, 'js', 'renderer.js'):   JS_RENDERER,
}

for path, content in files.items():
    with open(path, 'w', encoding='utf-8') as f:
        f.write(content)
    print(f"Written: {path}  ({len(content):,} bytes)")

print("All files written successfully.")

