renderer_js = '''
import { OBJECTS, ROOM, TILE_SIZE, project, unproject, isWalkable } from './world.js';

// Pokemon-style palette
const P = {
  floorA:'#5a7a3a', floorB:'#527035', floorGrid:'#3a5025',
  wall:'#2a1e0e', wallTop:'#3a2a16', wallLight:'#4a3820',
  wood:'#7a5c38', woodDark:'#5a4228', woodLight:'#9a7a52', woodEdge:'#3a2818',
  fabric:'#7a4a6a', fabricLight:'#9a6a8a', fabricDark:'#5a3050',
  screen:'#1a2a3a', screenGlow:'#3a8ab0', screenLine:'#2a5a7a',
  plantDark:'#2a5a1a', plantMid:'#3a7a28', plantLight:'#5a9a3a',
  plantPot:'#7a5a38', plantSoil:'#3a2818',
  board:'#d8e0c8', boardFrame:'#5a4828',
  metal:'#5a6a5a', metalDark:'#3a4a3a', metalLight:'#7a8a7a', metalHandle:'#9aaa9a',
  charSkin:'#d4956a', charHair:'#2a1e10', charShirt:'#3a5a8a',
  charPants:'#2a3a5a', charShoe:'#1a1410', charEye:'#1a1208',
  shadow:'rgba(0,0,0,0.32)',
  pathLine:'rgba(168,240,168,0.75)', pathDot:'#78e878',
  hoverTile:'rgba(168,240,168,0.15)', hoverBorder:'rgba(120,200,120,0.55)',
};

export class OfficeRenderer {
  constructor(canvas) {
    this.canvas = canvas;
    this.ctx = canvas.getContext("2d");
    this.width = 0; this.height = 0;
    this.zoom = 1; this.scale = 1;
    this.offset = { x:0, y:0 };
    this.hits = [];
    this.reducedMotion = matchMedia("(prefers-reduced-motion: reduce)").matches;
    this.resize();
  }

  resize() {
    const b = this.canvas.getBoundingClientRect();
    this.width = b.width; this.height = b.height;
    const dpr = Math.min(window.devicePixelRatio||1, 2);
    this.canvas.width  = Math.round(b.width  * dpr);
    this.canvas.height = Math.round(b.height * dpr);
    this.dpr = dpr;
    this.updateCamera();
  }

  updateCamera() {
    const rw = ROOM.width  * TILE_SIZE;
    const rh = ROOM.depth  * TILE_SIZE;
    const raw = Math.min(this.width/rw, this.height/rh) * this.zoom;
    this.scale = Math.max(1, Math.floor(raw));
    this.offset = {
      x: Math.round((this.width  - rw*this.scale) / 2),
      y: Math.round((this.height - rh*this.scale) / 2),
    };
  }

  screenPoint(tx, ty) {
    const p = project(tx, ty);
    return { x: Math.round(p.x*this.scale + this.offset.x),
             y: Math.round(p.y*this.scale + this.offset.y) };
  }

  floorPoint(sx, sy) {
    return unproject((sx-this.offset.x)/this.scale, (sy-this.offset.y)/this.scale);
  }

  floor() {
    const ctx = this.ctx, S = this.scale, T = TILE_SIZE*S;
    for (let ty=0; ty<ROOM.depth; ty++) {
      for (let tx=0; tx<ROOM.width; tx++) {
        const p = this.screenPoint(tx,ty);
        ctx.fillStyle = (tx+ty)%2===0 ? P.floorA : P.floorB;
        ctx.fillRect(p.x, p.y, T, T);
        ctx.fillStyle = P.floorGrid;
        ctx.fillRect(p.x, p.y, T, Math.max(1,S));
        ctx.fillRect(p.x, p.y, Math.max(1,S), T);
      }
    }
    const tl = this.screenPoint(0,0);
    const W = Math.round(ROOM.width*TILE_SIZE*S), H = Math.round(ROOM.depth*TILE_SIZE*S);
    const bw = Math.max(3,S*2);
    ctx.fillStyle = P.wall;
    ctx.fillRect(tl.x-bw, tl.y-bw*2, W+bw*2, bw*2);
    ctx.fillStyle = P.wallLight;
    ctx.fillRect(tl.x-bw, tl.y-bw, W+bw*2, bw);
    ctx.fillStyle = P.wall;
    ctx.fillRect(tl.x-bw*2, tl.y-bw*2, bw*2, H+bw*4);
    ctx.fillStyle = P.wallLight;
    ctx.fillRect(tl.x-bw, tl.y-bw, bw, H+bw*3);
    ctx.fillStyle = P.wall;
    ctx.fillRect(tl.x-bw, tl.y+H, W+bw*2, bw*2);
    ctx.fillRect(tl.x+W, tl.y-bw*2, bw*2, H+bw*4);
  }

  drawObject(obj, hovered) {
    this.hits.push(obj);
    const hot = hovered===obj.id;
    const S = this.scale, T = TILE_SIZE*S;
    const p = this.screenPoint(obj.x, obj.y);
    const W = Math.round(obj.w*T), H = Math.round(obj.d*T);
    const ctx = this.ctx;
    const s2=Math.round(S*2), s1=Math.max(1,Math.round(S));
    ctx.fillStyle = P.shadow;
    ctx.fillRect(p.x+s2, p.y+s2, W, H);
    switch(obj.type) {
      case "plant": {
        const px=p.x+Math.round(T*.2), potW=Math.round(T*.6);
        const potTop=p.y+Math.round(T*.55), potH=Math.round(T*.35);
        ctx.fillStyle=P.plantSoil; ctx.fillRect(px,potTop,potW,s1);
        ctx.fillStyle=P.plantPot;  ctx.fillRect(px,potTop+s1,potW,potH);
        const lx=p.x+Math.round(T*.15), ly=p.y+Math.round(T*.05);
        const lw=Math.round(T*.7), lh=Math.round(T*.55);
        ctx.fillStyle=P.plantDark; ctx.fillRect(lx+s1,ly+s1,lw-s2,lh);
        ctx.fillStyle=hot?P.plantLight:P.plantMid;
        ctx.fillRect(lx,ly+Math.round(lh*.2),lw,Math.round(lh*.6));
        ctx.fillRect(lx+Math.round(lw*.15),ly,Math.round(lw*.7),lh);
        break;
      }
      case "board": {
        const fw=s2;
        ctx.fillStyle=P.boardFrame; ctx.fillRect(p.x,p.y,W,H);
        ctx.fillStyle=hot?"#e8ead8":P.board;
        ctx.fillRect(p.x+fw,p.y+fw,W-fw*2,H-fw*2);
        const nc=["#e8c840","#e84040","#40b8e8"];
        for(let i=0;i<3;i++){
          ctx.fillStyle=nc[i];
          ctx.fillRect(p.x+fw+Math.round((W-fw*2)*(.1+i*.3)), p.y+fw+Math.round((H-fw*2)*.2), Math.round(S*4), Math.round(S*4));
        }
        break;
      }
      case "cabinet": {
        ctx.fillStyle=hot?P.metalLight:P.metal; ctx.fillRect(p.x,p.y,W,H);
        const doors=obj.d>=2?2:1, dH=Math.round(H/doors);
        for(let d=0;d<doors;d++){
          const dy=p.y+d*dH;
          if(d>0){ctx.fillStyle=P.metalDark;ctx.fillRect(p.x,dy,W,s1);}
          ctx.fillStyle=P.metalHandle;
          ctx.fillRect(p.x+Math.round(W*.42), dy+Math.round(dH*.45), s2, Math.round(S*1.5));
        }
        ctx.strokeStyle=P.metalDark; ctx.lineWidth=s1;
        ctx.strokeRect(p.x+.5,p.y+.5,W-1,H-1);
        break;
      }
      case "shelf": {
        ctx.fillStyle=P.woodDark; ctx.fillRect(p.x,p.y,W,H);
        const shelves=3, shH=Math.round(H/shelves);
        const bc=["#d05030","#4878b8","#e8a030","#5ab048","#9848a8"];
        for(let s=0;s<shelves;s++){
          const sy=p.y+s*shH;
          ctx.fillStyle=P.wood; ctx.fillRect(p.x,sy,W,Math.max(2,Math.round(S*1.5)));
          const bCnt=Math.floor(obj.w*3), bw2=Math.round((W-s1)/bCnt);
          for(let b=0;b<bCnt;b++){
            ctx.fillStyle=bc[(b+s)%bc.length];
            const bh=Math.round(shH*(.55+((b*7+s*3)%4)*.1));
            ctx.fillRect(p.x+Math.round(S*.5)+b*bw2, sy+Math.round(S*1.5), bw2-Math.max(1,Math.round(S*.5)), bh);
          }
        }
        break;
      }
      case "desk": {
        ctx.fillStyle=P.woodEdge; ctx.fillRect(p.x,p.y,W,H);
        ctx.fillStyle=hot?P.woodLight:P.wood;
        const e=Math.round(S*1.5);
        ctx.fillRect(p.x+e,p.y+e,W-e*2,H-e*2);
        const mw=Math.round(W*.38), mh=Math.round(H*.5);
        const mx=p.x+Math.round(W*.35), my=p.y+Math.round(H*.15);
        ctx.fillStyle=P.screen;    ctx.fillRect(mx,my,mw,mh);
        ctx.fillStyle=P.screenGlow; ctx.fillRect(mx+s1,my+s1,mw-s2,mh-s2);
        for(let sl=0;sl<3;sl++){
          ctx.fillStyle=P.screenLine;
          ctx.fillRect(mx+s1, my+s2+sl*s2, mw-s2, s1);
        }
        const kw=Math.round(W*.35);
        ctx.fillStyle=P.metalDark; ctx.fillRect(p.x+Math.round(W*.33), my+mh+s2, kw, s2);
        break;
      }
      case "desk-small": {
        ctx.fillStyle=P.woodEdge; ctx.fillRect(p.x,p.y,W,H);
        ctx.fillStyle=hot?P.woodLight:P.wood;
        const e2=Math.round(S*1.5);
        ctx.fillRect(p.x+e2,p.y+e2,W-e2*2,H-e2*2);
        ctx.fillStyle="#e8e0c8";
        ctx.fillRect(p.x+Math.round(W*.2),p.y+Math.round(H*.2),Math.round(W*.35),Math.round(H*.45));
        break;
      }
      case "chair": {
        const so=Math.round(T*.25), sw=Math.round(T*.5);
        ctx.fillStyle=hot?P.fabricLight:P.fabric;
        ctx.fillRect(p.x+so,p.y+Math.round(T*.05),sw,Math.round(T*.35));
        ctx.fillRect(p.x+so,p.y+Math.round(T*.38),sw,Math.round(T*.35));
        ctx.fillStyle=P.metalDark;
        ctx.fillRect(p.x+so,p.y+Math.round(T*.72),Math.round(S*1.5),Math.round(S*1.5));
        ctx.fillRect(p.x+so+sw-Math.round(S*1.5),p.y+Math.round(T*.72),Math.round(S*1.5),Math.round(S*1.5));
        break;
      }
      case "sofa": {
        ctx.fillStyle=P.fabricDark; ctx.fillRect(p.x,p.y,W,H);
        ctx.fillStyle=P.fabric; ctx.fillRect(p.x,p.y,W,Math.round(H*.28));
        const cw=Math.round(W*.42);
        ctx.fillStyle=hot?P.fabricLight:P.fabric;
        ctx.fillRect(p.x+s1,p.y+Math.round(H*.25),cw,Math.round(H*.6));
        ctx.fillRect(p.x+Math.round(W*.52),p.y+Math.round(H*.25),cw,Math.round(H*.6));
        ctx.fillStyle=P.fabricDark;
        ctx.fillRect(p.x,p.y,Math.round(W*.1),H);
        ctx.fillRect(p.x+W-Math.round(W*.1),p.y,Math.round(W*.1),H);
        break;
      }
      case "table": {
        ctx.fillStyle=P.woodEdge; ctx.fillRect(p.x,p.y,W,H);
        ctx.fillStyle=hot?P.woodLight:P.wood;
        const te=s2;
        ctx.fillRect(p.x+te,p.y+te,W-te*2,H-te*2);
        const cup=Math.round(S*2.5);
        ctx.fillStyle="#e8e0c8";
        ctx.fillRect(p.x+Math.round(W*.2),p.y+Math.round(H*.3),cup,cup);
        ctx.fillRect(p.x+Math.round(W*.6),p.y+Math.round(H*.3),cup,cup);
        break;
      }
      default: {
        ctx.fillStyle=hot?"#8a7a6a":"#6a5a4a";
        ctx.fillRect(p.x,p.y,W,H);
        ctx.strokeStyle="#3a2a1a"; ctx.lineWidth=s1;
        ctx.strokeRect(p.x+.5,p.y+.5,W-1,H-1);
      }
    }
  }

  character(founder, moving, time) {
    const S=this.scale, T=TILE_SIZE*S;
    const p=this.screenPoint(founder.x, founder.y);
    const cx=p.x+Math.round(T*.5), cy=p.y+Math.round(T*.5);
    const ctx=this.ctx;
    const frame=(moving&&!this.reducedMotion)?Math.floor(time/150)%2:0;
    const u=Math.round(S);
    // shadow
    ctx.fillStyle="rgba(0,0,0,0.3)";
    ctx.beginPath();
    ctx.ellipse(cx, cy+Math.round(T*.28), Math.round(T*.22), Math.round(T*.08), 0, 0, Math.PI*2);
    ctx.fill();
    // shoes
    ctx.fillStyle=P.charShoe;
    if(frame===0){
      ctx.fillRect(cx-u*3,cy+u*5,u*2,u*3); ctx.fillRect(cx+u,cy+u*5,u*2,u*3);
    } else {
      ctx.fillRect(cx-u*3,cy+u*6,u*2,u*2); ctx.fillRect(cx+u,cy+u*4,u*2,u*4);
    }
    // pants
    ctx.fillStyle=P.charPants;
    ctx.fillRect(cx-u*3,cy+u,u*2,u*5); ctx.fillRect(cx+u,cy+u,u*2,u*5);
    // shirt
    ctx.fillStyle=P.charShirt; ctx.fillRect(cx-u*4,cy-u*5,u*8,u*7);
    // arms
    if(frame===0){
      ctx.fillRect(cx-u*6,cy-u*4,u*2,u*5); ctx.fillRect(cx+u*4,cy-u*4,u*2,u*5);
    } else {
      ctx.fillRect(cx-u*6,cy-u*5,u*2,u*5); ctx.fillRect(cx+u*4,cy-u*3,u*2,u*5);
    }
    // neck + head
    ctx.fillStyle=P.charSkin;
    ctx.fillRect(cx-u,cy-u*6,u*2,u*2);
    ctx.fillRect(cx-u*4,cy-u*13,u*8,u*8);
    // hair
    ctx.fillStyle=P.charHair;
    ctx.fillRect(cx-u*4,cy-u*13,u*8,u*3);
    ctx.fillRect(cx-u*4,cy-u*10,u*2,u*2);
    // eyes
    ctx.fillStyle=P.charEye;
    ctx.fillRect(cx-u*3,cy-u*9,u*2,u*2);
    ctx.fillRect(cx+u,cy-u*9,u*2,u*2);
    ctx.fillStyle="#ffffff";
    ctx.fillRect(cx-u*2,cy-u*9,u,u);
    ctx.fillRect(cx+u*2,cy-u*9,u,u);
    // nametag
    ctx.save();
    ctx.font="bold "+(Math.max(7,S*5))+"px \'Courier New\', monospace";
    ctx.textAlign="center";
    ctx.fillStyle="rgba(0,0,0,0.5)";
    ctx.fillText("ALEX", cx+u, cy-Math.round(T*.7)+u);
    ctx.fillStyle="#a8f0a8";
    ctx.fillText("ALEX", cx, cy-Math.round(T*.7));
    ctx.restore();
  }

  path(pathArr, founder, time) {
    if(!pathArr.length) return;
    const ctx=this.ctx, S=this.scale, T=TILE_SIZE*S;
    ctx.save();
    ctx.setLineDash([Math.round(S*3),Math.round(S*4)]);
    ctx.lineDashOffset=this.reducedMotion?0:-(time/80);
    ctx.strokeStyle=P.pathLine; ctx.lineWidth=Math.max(1,Math.round(S*1.5));
    ctx.beginPath();
    const sp=this.screenPoint(founder.x,founder.y);
    ctx.moveTo(sp.x+Math.round(T/2), sp.y+Math.round(T/2));
    for(const wp of pathArr){
      const pp=this.screenPoint(wp.x,wp.y);
      ctx.lineTo(pp.x+Math.round(T/2), pp.y+Math.round(T/2));
    }
    ctx.stroke(); ctx.restore();
    const last=pathArr[pathArr.length-1];
    const lp=this.screenPoint(Math.floor(last.x),Math.floor(last.y));
    const pulse=this.reducedMotion?1:0.6+Math.sin(time/180)*.4;
    const ms=Math.round(T*.3);
    ctx.fillStyle="rgba(120,232,120,"+pulse+")";
    ctx.fillRect(lp.x+Math.round(T/2)-Math.round(ms/2), lp.y+Math.round(T/2)-Math.round(ms/2), ms, ms);
  }

  render({founder,path,hovered,hoverFloor,moving,time}) {
    const ctx=this.ctx;
    ctx.imageSmoothingEnabled=false;
    ctx.setTransform(this.dpr,0,0,this.dpr,0,0);
    ctx.fillStyle="#0a0a0f"; ctx.fillRect(0,0,this.width,this.height);
    this.floor();
    this.path(path,founder,time);
    if(hoverFloor&&!hovered&&isWalkable(hoverFloor.x,hoverFloor.y)){
      const hp=this.screenPoint(Math.floor(hoverFloor.x),Math.floor(hoverFloor.y));
      const T=TILE_SIZE*this.scale;
      ctx.fillStyle=P.hoverTile; ctx.fillRect(hp.x,hp.y,T,T);
      ctx.strokeStyle=P.hoverBorder; ctx.lineWidth=Math.max(1,Math.round(this.scale));
      ctx.strokeRect(hp.x+.5,hp.y+.5,T-1,T-1);
    }
    this.hits=[];
    const entries=OBJECTS.map(o=>({o,depth:o.y+o.d}));
    entries.push({player:true,depth:founder.y+1});
    entries.sort((a,b)=>a.depth-b.depth);
    for(const entry of entries){
      if(entry.player) this.character(founder,moving,time);
      else this.drawObject(entry.o,hovered);
    }
  }

  hitTest(sx,sy){
    const wp=this.floorPoint(sx,sy);
    for(const o of [...this.hits].reverse()){
      if(wp.x>=o.x&&wp.x<o.x+o.w&&wp.y>=o.y&&wp.y<o.y+o.d) return o;
    }
    return null;
  }
}
