import { OBJECTS, ROOM, TILE_SIZE, project, unproject, isWalkable } from './world.js';

const P = {
  floorA:'#5a7a3a', floorB:'#527035', floorGrid:'#3a5025',
  wall:'#2a1e0e', wallLight:'#4a3820',
  wood:'#7a5c38', woodDark:'#5a4228', woodLight:'#9a7a52', woodEdge:'#3a2818',
  fabric:'#7a4a6a', fabricLight:'#9a6a8a', fabricDark:'#5a3050',
  screen:'#1a2a3a', screenGlow:'#3a8ab0', screenLine:'#2a5a7a',
  plantDark:'#2a5a1a', plantMid:'#3a7a28', plantLight:'#5a9a3a',
  plantPot:'#7a5a38', plantSoil:'#3a2818',
  board:'#d8e0c8', boardFrame:'#5a4828',
  metal:'#5a6a5a', metalDark:'#3a4a3a', metalLight:'#7a8a7a', metalHandle:'#9aaa9a',
  charSkin:'#d4956a', charHair:'#2a1e10', charShirt:'#3a5a8a',
  charPants:'#2a3a5a', charShoe:'#1a1410', charEye:'#1a1208',
  shadow:'rgba(0,0,0,0.32)',
  pathLine:'rgba(168,240,168,0.75)',
  hoverTile:'rgba(168,240,168,0.15)', hoverBorder:'rgba(120,200,120,0.55)',
};

export class OfficeRenderer {
  constructor(canvas) {
    this.canvas = canvas;
    this.ctx = canvas.getContext('2d');
    this.width = 0; this.height = 0;
    this.zoom = 1; this.scale = 1;
    this.offset = { x:0, y:0 };
    this.hits = [];
    this.reducedMotion = matchMedia('(prefers-reduced-motion: reduce)').matches;
    this.resize();
  }

  resize() {
    const b = this.canvas.getBoundingClientRect();
    this.width = b.width; this.height = b.height;
    const dpr = Math.min(window.devicePixelRatio||1, 2);
    this.canvas.width  = Math.round(b.width  * dpr);
    this.canvas.height = Math.round(b.height * dpr);
    this.dpr = dpr;
    this.updateCamera();
  }

  updateCamera() {
    const rw = ROOM.width  * TILE_SIZE;
    const rh = ROOM.depth  * TILE_SIZE;
    const raw = Math.min(this.width/rw, this.height/rh) * this.zoom;
    this.scale = Math.max(1, Math.floor(raw));
    this.offset = {
      x: Math.round((this.width  - rw*this.scale) / 2),
      y: Math.round((this.height - rh*this.scale) / 2),
    };
  }

  screenPoint(tx, ty) {
    const p = project(tx, ty);
    return { x: Math.round(p.x*this.scale + this.offset.x),
             y: Math.round(p.y*this.scale + this.offset.y) };
  }

  floorPoint(sx, sy) {
    return unproject((sx-this.offset.x)/this.scale, (sy-this.offset.y)/this.scale);
  }

  floor() {
    const ctx = this.ctx, S = this.scale, T = TILE_SIZE*S;
    for (let ty=0; ty<ROOM.depth; ty++) {
      for (let tx=0; tx<ROOM.width; tx++) {
        const p = this.screenPoint(tx, ty);
        ctx.fillStyle = (tx+ty)%2===0 ? P.floorA : P.floorB;
        ctx.fillRect(p.x, p.y, T, T);
        ctx.fillStyle = P.floorGrid;
        ctx.fillRect(p.x, p.y, T, Math.max(1,S));
        ctx.fillRect(p.x, p.y, Math.max(1,S), T);
      }
    }
    const tl = this.screenPoint(0,0);
    const W = Math.round(ROOM.width*TILE_SIZE*S);
    const H = Math.round(ROOM.depth*TILE_SIZE*S);
    const bw = Math.max(3, S*2);
    ctx.fillStyle = P.wall;
    ctx.fillRect(tl.x-bw, tl.y-bw*2, W+bw*2, bw*2);
    ctx.fillStyle = P.wallLight;
    ctx.fillRect(tl.x-bw, tl.y-bw, W+bw*2, bw);
    ctx.fillStyle = P.wall;
    ctx.fillRect(tl.x-bw*2, tl.y-bw*2, bw*2, H+bw*4);
    ctx.fillStyle = P.wallLight;
    ctx.fillRect(tl.x-bw, tl.y-bw, bw, H+bw*3);
    ctx.fillStyle = P.wall;
    ctx.fillRect(tl.x-bw, tl.y+H, W+bw*2, bw*2);
    ctx.fillRect(tl.x+W, tl.y-bw*2, bw*2, H+bw*4);
  }

  // DRAWOBJECT_PLACEHOLDER

