// DRAWOBJECT_PLACEHOLDER

drawObject(obj, hovered) {
  this.hits.push(obj);
  const hot = hovered===obj.id;
  const S = this.scale, T = TILE_SIZE*S;
  const p = this.screenPoint(obj.x, obj.y);
  const W = Math.round(obj.w*T), H = Math.round(obj.d*T);
  const ctx = this.ctx;
  const s2=Math.round(S*2), s1=Math.max(1,Math.round(S));
  ctx.fillStyle = P.shadow;
  ctx.fillRect(p.x+s2, p.y+s2, W, H);
  switch(obj.type) {
    case 'plant': {
      const px=p.x+Math.round(T*.2), potW=Math.round(T*.6);
      const potTop=p.y+Math.round(T*.55), potH=Math.round(T*.35);
      ctx.fillStyle=P.plantSoil; ctx.fillRect(px,potTop,potW,s1);
      ctx.fillStyle=P.plantPot;  ctx.fillRect(px,potTop+s1,potW,potH);
      const lx=p.x+Math.round(T*.15), ly=p.y+Math.round(T*.05);
      const lw=Math.round(T*.7), lh=Math.round(T*.55);
      ctx.fillStyle=P.plantDark; ctx.fillRect(lx+s1,ly+s1,lw-s2,lh);
      ctx.fillStyle=hot?P.plantLight:P.plantMid;
      ctx.fillRect(lx,ly+Math.round(lh*.2),lw,Math.round(lh*.6));
      ctx.fillRect(lx+Math.round(lw*.15),ly,Math.round(lw*.7),lh);
      break;
    }
    case 'board': {
      ctx.fillStyle=P.boardFrame; ctx.fillRect(p.x,p.y,W,H);
      ctx.fillStyle=hot?'#e8ead8':P.board;
      ctx.fillRect(p.x+s2,p.y+s2,W-s2*2,H-s2*2);
      const nc=['#e8c840','#e84040','#40b8e8'];
      for(let i=0;i<3;i++) {
        ctx.fillStyle=nc[i];
        ctx.fillRect(p.x+s2+Math.round((W-s2*2)*(.1+i*.3)), p.y+s2+Math.round((H-s2*2)*.2), Math.round(S*4), Math.round(S*4));
      }
      ctx.fillStyle='#a8b898';
      for(let l=0;l<2;l++)
        ctx.fillRect(p.x+s2+s1, p.y+s2+Math.round((H-s2*2)*(.55+l*.25)), W-s2*2-s2, s1);
      break;
    }
    case 'cabinet': {
      ctx.fillStyle=hot?P.metalLight:P.metal; ctx.fillRect(p.x,p.y,W,H);
      const doors=obj.d>=2?2:1, dH=Math.round(H/doors);
      for(let d=0;d<doors;d++) {
        const dy=p.y+d*dH;
        if(d>0){ctx.fillStyle=P.metalDark;ctx.fillRect(p.x,dy,W,s1);}
        ctx.fillStyle=P.metalHandle;
        ctx.fillRect(p.x+Math.round(W*.42), dy+Math.round(dH*.45), s2, Math.round(S*1.5));
      }
      ctx.strokeStyle=P.metalDark; ctx.lineWidth=s1;
      ctx.strokeRect(p.x+.5,p.y+.5,W-1,H-1);
      break;
    }
    case 'shelf': {
      ctx.fillStyle=P.woodDark; ctx.fillRect(p.x,p.y,W,H);
      const shelves=3, shH=Math.round(H/shelves);
      const bc=['#d05030','#4878b8','#e8a030','#5ab048','#9848a8'];
      for(let s=0;s<shelves;s++) {
        const sy=p.y+s*shH;
        ctx.fillStyle=P.wood; ctx.fillRect(p.x,sy,W,Math.max(2,Math.round(S*1.5)));
        const bCnt=Math.floor(obj.w*3), bw2=Math.round((W-s1)/bCnt);
        for(let b=0;b<bCnt;b++) {
          ctx.fillStyle=bc[(b+s)%bc.length];
          const bh=Math.round(shH*(.55+((b*7+s*3)%4)*.1));
          ctx.fillRect(p.x+Math.round(S*.5)+b*bw2, sy+Math.round(S*1.5), bw2-Math.max(1,Math.round(S*.5)), bh);
        }
      }
      break;
    }
    case 'desk': {
      ctx.fillStyle=P.woodEdge; ctx.fillRect(p.x,p.y,W,H);
      ctx.fillStyle=hot?P.woodLight:P.wood;
      const e=Math.round(S*1.5);
      ctx.fillRect(p.x+e,p.y+e,W-e*2,H-e*2);
      const mw=Math.round(W*.38), mh=Math.round(H*.5);
      const mx=p.x+Math.round(W*.35), my=p.y+Math.round(H*.15);
      ctx.fillStyle=P.screen; ctx.fillRect(mx,my,mw,mh);
      ctx.fillStyle=P.screenGlow; ctx.fillRect(mx+s1,my+s1,mw-s2,mh-s2);
      ctx.fillStyle=P.screenLine;
      for(let sl=0;sl<3;sl++) ctx.fillRect(mx+s1, my+s2+sl*s2, mw-s2, s1);
      ctx.fillStyle=P.metalDark;
      ctx.fillRect(p.x+Math.round(W*.33), my+mh+s2, Math.round(W*.35), s2);
      break;
    }
    case 'desk-small': {
      ctx.fillStyle=P.woodEdge; ctx.fillRect(p.x,p.y,W,H);
      ctx.fillStyle=hot?P.woodLight:P.wood;
      const e2=Math.round(S*1.5);
      ctx.fillRect(p.x+e2,p.y+e2,W-e2*2,H-e2*2);
      ctx.fillStyle='#e8e0c8';
      ctx.fillRect(p.x+Math.round(W*.2),p.y+Math.round(H*.2),Math.round(W*.35),Math.round(H*.45));
      break;
    }
    case 'chair': {
      const so=Math.round(T*.25), sw=Math.round(T*.5);
      ctx.fillStyle=hot?P.fabricLight:P.fabric;
      ctx.fillRect(p.x+so,p.y+Math.round(T*.05),sw,Math.round(T*.35));
      ctx.fillRect(p.x+so,p.y+Math.round(T*.38),sw,Math.round(T*.35));
      ctx.fillStyle=P.metalDark; const ls=Math.round(S*1.5);
      ctx.fillRect(p.x+so,p.y+Math.round(T*.72),ls,ls);
      ctx.fillRect(p.x+so+sw-ls,p.y+Math.round(T*.72),ls,ls);
      break;
    }
    case 'sofa': {
      ctx.fillStyle=P.fabricDark; ctx.fillRect(p.x,p.y,W,H);
      ctx.fillStyle=P.fabric; ctx.fillRect(p.x,p.y,W,Math.round(H*.28));
      const cw=Math.round(W*.42);
      ctx.fillStyle=hot?P.fabricLight:P.fabric;
      ctx.fillRect(p.x+s1,p.y+Math.round(H*.25),cw,Math.round(H*.6));
      ctx.fillRect(p.x+Math.round(W*.52),p.y+Math.round(H*.25),cw,Math.round(H*.6));
      ctx.fillStyle=P.fabricDark;
      ctx.fillRect(p.x,p.y,Math.round(W*.1),H);
      ctx.fillRect(p.x+W-Math.round(W*.1),p.y,Math.round(W*.1),H);
      break;
    }
    case 'table': {
      ctx.fillStyle=P.woodEdge; ctx.fillRect(p.x,p.y,W,H);
      ctx.fillStyle=hot?P.woodLight:P.wood;
      ctx.fillRect(p.x+s2,p.y+s2,W-s2*2,H-s2*2);
      const cup=Math.round(S*2.5);
      ctx.fillStyle='#e8e0c8';
      ctx.fillRect(p.x+Math.round(W*.2),p.y+Math.round(H*.3),cup,cup);
      ctx.fillRect(p.x+Math.round(W*.6),p.y+Math.round(H*.3),cup,cup);
      break;
    }
    default: {
      ctx.fillStyle=hot?'#8a7a6a':'#6a5a4a'; ctx.fillRect(p.x,p.y,W,H);
      ctx.strokeStyle='#3a2a1a'; ctx.lineWidth=s1;
      ctx.strokeRect(p.x+.5,p.y+.5,W-1,H-1);
    }
  }
}

