function save() {
  try {
    localStorage.setItem(SAVE_KEY, JSON.stringify(state));
    storageAvailable = true;
  } catch { storageAvailable = false; }
  $('#save-status').innerHTML = `<i></i> ${storageAvailable ? 'Saved locally' : 'Playing without saves'}`;
}

function updateUI() {
  const hour = Math.floor(state.minutes / 60);
  $('#clock').textContent = `${hour % 12 || 12}:${String(Math.floor(state.minutes % 60)).padStart(2, '0')} ${hour >= 12 ? 'PM' : 'AM'}`;
  $('#energy-value').innerHTML = `${Math.round(state.energy)}<span>/100</span>`;
  $('#energy-bar').setAttribute('aria-valuenow', String(Math.round(state.energy)));
  $('#energy-bar > span').style.width = `${state.energy}%`;
  $('#energy-bar > span').style.background = state.energy < 25 ? '#d6a16e' : '#98ad7c';
  for (const task of document.querySelectorAll('[data-task]')) {
    const completed = state.completed.includes(task.dataset.task);
    task.classList.toggle('complete', completed);
    task.setAttribute('aria-label', `${task.querySelector('strong').textContent}${completed ? ', completed' : ', walk to this task'}`);
  }
  const count = state.completed.length;
  $('#task-count').textContent = `${count} / ${TASKS.length}`;
  $('#task-progress').style.width = `${count / TASKS.length * 100}%`;
  $('#completion-note').textContent = count === TASKS.length ? 'Day one, done. This is only the beginning. ✧' : 'Every great company has a day one.';
  $('#founder-hint').style.opacity = state.distance > .2 ? '0' : '1';
  const soundButton = $('#sound-button');
  soundButton.setAttribute('aria-pressed', String(state.sound));
  soundButton.setAttribute('aria-label', `Turn sound ${state.sound ? 'off' : 'on'}`);
  soundButton.title = `Turn sound ${state.sound ? 'off' : 'on'}`;
  $('#founder-status').textContent = paused ? 'Taking a breather' : path.length ? 'Finding the way, one step at a time' : state.energy < 25 ? 'Could use a coffee break' : count === 4 ? 'A little closer to the big idea' : 'Ready for a fresh start';
}

function complete(id) {
  if (state.completed.includes(id)) return;
  state.completed.push(id);
  updateUI();
  save();
  if (id === 'walk') { toast('First steps, taken. Welcome to your little headquarters.'); playSound('complete'); }

