 20 | export class OfficeRenderer {
 21 |   constructor(canvas) {
 22 |     this.canvas = canvas;
 23 |     this.ctx = canvas.getContext('2d');
 24 |     this.width = 0; this.height = 0;
 25 |     this.zoom = 1; this.scale = 1;
 26 |     this.offset = { x:0, y:0 };
 27 |     this.hits = [];
 28 |     this.reducedMotion = matchMedia('(prefers-reduced-motion: reduce)').matches;
 29 |     this.resize();
 30 |   }
 31 | 
 32 |   resize() {
 33 |     const b = this.canvas.getBoundingClientRect();
 34 |     this.width = b.width; this.height = b.height;
 35 |     const dpr = Math.min(window.devicePixelRatio||1, 2);
 36 |     this.canvas.width  = Math.round(b.width  * dpr);
 37 |     this.canvas.height = Math.round(b.height * dpr);
 38 |     this.dpr = dpr;
 39 |     this.updateCamera();
 40 |   }
 41 | 
 42 |   updateCamera() {
 43 |     const rw = ROOM.width  * TILE_SIZE;
 44 |     const rh = ROOM.depth  * TILE_SIZE;
 45 |     const raw = Math.min(this.width/rw, this.height/rh) * this.zoom;
 46 |     this.scale = Math.max(1, Math.floor(raw));
 47 |     this.offset = {
 48 |       x: Math.round((this.width  - rw*this.scale) / 2),
 49 |       y: Math.round((this.height - rh*this.scale) / 2),
 50 |     };
 51 |   }
 52 | 
 53 |   screenPoint(tx, ty) {
 54 |     const p = project(tx, ty);
 55 |     return { x: Math.round(p.x*this.scale + this.offset.x),
 56 |              y: Math.round(p.y*this.scale + this.offset.y) };
 57 |   }
 58 | 
 59 |   floorPoint(sx, sy) {
 60 |     return unproject((sx-this.offset.x)/this.scale, (sy-this.offset.y)/this.scale);
 61 |   }
 62 | 
 63 |   floor() {
 64 |     const ctx = this.ctx, S = this.scale, T = TILE_SIZE*S;
 65 |     for (let ty=0; ty<ROOM.depth; ty++) {
 66 |       for (let tx=0; tx<ROOM.width; tx++) {
 67 |         const p = this.screenPoint(tx, ty);
 68 |         ctx.fillStyle = (tx+ty)%2===0 ? P.floorA : P.floorB;
 69 |         ctx.fillRect(p.x, p.y, T, T);
 70 |         ctx.fillStyle = P.floorGrid;
 71 |         ctx.fillRect(p.x, p.y, T, Math.max(1,S));
 72 |         ctx.fillRect(p.x, p.y, Math.max(1,S), T);
 73 |       }
 74 |     }
 75 |     const tl = this.screenPoint(0,0);
 76 |     const W = Math.round(ROOM.width*TILE_SIZE*S);
 77 |     const H = Math.round(ROOM.depth*TILE_SIZE*S);
 78 |     const bw = Math.max(3, S*2);
 79 |     ctx.fillStyle = P.wall;
 80 |     ctx.fillRect(tl.x-bw, tl.y-bw*2, W+bw*2, bw*2);
 81 |     ctx.fillStyle = P.wallLight;
 82 |     ctx.fillRect(tl.x-bw, tl.y-bw, W+bw*2, bw);
 83 |     ctx.fillStyle = P.wall;
 84 |     ctx.fillRect(tl.x-bw*2, tl.y-bw*2, bw*2, H+bw*4);
 85 |     ctx.fillStyle = P.wallLight;
 86 |     ctx.fillRect(tl.x-bw, tl.y-bw, bw, H+bw*3);
 87 |     ctx.fillStyle = P.wall;
 88 |     ctx.fillRect(tl.x-bw, tl.y+H, W+bw*2, bw*2);
 89 |     ctx.fillRect(tl.x+W, tl.y-bw*2, bw*2, H+bw*4);
 90 |   }
