227 |   character(founder, moving, time) {
228 |     const S=this.scale, T=TILE_SIZE*S;
229 |     const p=this.screenPoint(founder.x, founder.y);
230 |     const cx=p.x+Math.round(T*.5), cy=p.y+Math.round(T*.5);
231 |     const ctx=this.ctx;
232 |     const frame=(moving&&!this.reducedMotion)?Math.floor(time/150)%2:0;
233 |     const u=Math.round(S);
234 |     ctx.fillStyle='rgba(0,0,0,0.3)';
235 |     ctx.beginPath();
236 |     ctx.ellipse(cx, cy+Math.round(T*.28), Math.round(T*.22), Math.round(T*.08), 0, 0, Math.PI*2);
237 |     ctx.fill();
238 |     ctx.fillStyle=P.charShoe;
239 |     if(frame===0) {
240 |       ctx.fillRect(cx-u*3,cy+u*5,u*2,u*3); ctx.fillRect(cx+u,cy+u*5,u*2,u*3);
241 |     } else {
242 |       ctx.fillRect(cx-u*3,cy+u*6,u*2,u*2); ctx.fillRect(cx+u,cy+u*4,u*2,u*4);
243 |     }
244 |     ctx.fillStyle=P.charPants;
245 |     ctx.fillRect(cx-u*3,cy+u,u*2,u*5); ctx.fillRect(cx+u,cy+u,u*2,u*5);
246 |     ctx.fillStyle=P.charShirt; ctx.fillRect(cx-u*4,cy-u*5,u*8,u*7);
247 |     if(frame===0) {
248 |       ctx.fillRect(cx-u*6,cy-u*4,u*2,u*5); ctx.fillRect(cx+u*4,cy-u*4,u*2,u*5);
249 |     } else {
250 |       ctx.fillRect(cx-u*6,cy-u*5,u*2,u*5); ctx.fillRect(cx+u*4,cy-u*3,u*2,u*5);
251 |     }
252 |     ctx.fillStyle=P.charSkin;
253 |     ctx.fillRect(cx-u,cy-u*6,u*2,u*2);
254 |     ctx.fillRect(cx-u*4,cy-u*13,u*8,u*8);
255 |     ctx.fillStyle=P.charHair;
256 |     ctx.fillRect(cx-u*4,cy-u*13,u*8,u*3);
257 |     ctx.fillRect(cx-u*4,cy-u*10,u*2,u*2);
258 |     ctx.fillStyle=P.charEye;
259 |     ctx.fillRect(cx-u*3,cy-u*9,u*2,u*2);
260 |     ctx.fillRect(cx+u,cy-u*9,u*2,u*2);
261 |     ctx.fillStyle='#ffffff';
262 |     ctx.fillRect(cx-u*2,cy-u*9,u,u);
263 |     ctx.fillRect(cx+u*2,cy-u*9,u,u);
264 |     ctx.save();
265 |     ctx.font='bold '+(Math.max(7,S*5))+'px \'Courier New\', monospace';
266 |     ctx.textAlign='center';
267 |     ctx.fillStyle='rgba(0,0,0,0.5)';
268 |     ctx.fillText('ALEX', cx+u, cy-Math.round(T*.7)+u);
269 |     ctx.fillStyle='#a8f0a8';
270 |     ctx.fillText('ALEX', cx, cy-Math.round(T*.7));
271 |     ctx.restore();
272 |   }
