274 |   path(pathArr, founder, time) {
275 |     if(!pathArr.length) return;
276 |     const ctx=this.ctx, S=this.scale, T=TILE_SIZE*S;
277 |     ctx.save();
278 |     ctx.setLineDash([Math.round(S*3),Math.round(S*4)]);
279 |     ctx.lineDashOffset=this.reducedMotion?0:-(time/80);
280 |     ctx.strokeStyle=P.pathLine; ctx.lineWidth=Math.max(1,Math.round(S*1.5));
281 |     ctx.beginPath();
282 |     const sp=this.screenPoint(founder.x,founder.y);
283 |     ctx.moveTo(sp.x+Math.round(T/2), sp.y+Math.round(T/2));
284 |     for(const wp of pathArr) {
285 |       const pp=this.screenPoint(wp.x,wp.y);
286 |       ctx.lineTo(pp.x+Math.round(T/2), pp.y+Math.round(T/2));
287 |     }
288 |     ctx.stroke(); ctx.restore();
289 |     const last=pathArr[pathArr.length-1];
290 |     const lp=this.screenPoint(Math.floor(last.x),Math.floor(last.y));
291 |     const pulse=this.reducedMotion?1:0.6+Math.sin(time/180)*.4;
292 |     const ms=Math.round(T*.3);
293 |     const mx=lp.x+Math.round(T/2)-Math.round(ms/2);
294 |     const my=lp.y+Math.round(T/2)-Math.round(ms/2);
295 |     ctx.fillStyle=`rgba(120,232,120,${pulse})`;
296 |     ctx.fillRect(mx, my, ms, ms);
297 |     ctx.fillStyle='rgba(20,40,20,0.4)';
298 |     ctx.fillRect(mx+Math.round(S), my+Math.round(S), ms-Math.round(S*2), ms-Math.round(S*2));
299 |   }
300 | 
301 |   render({founder,path,hovered,hoverFloor,moving,time}) {
302 |     const ctx=this.ctx;
303 |     ctx.imageSmoothingEnabled=false;
304 |     ctx.setTransform(this.dpr,0,0,this.dpr,0,0);
305 |     ctx.fillStyle='#0a0a0f'; ctx.fillRect(0,0,this.width,this.height);
306 |     this.floor();
307 |     this.path(path,founder,time);
308 |     if(hoverFloor&&!hovered&&isWalkable(hoverFloor.x,hoverFloor.y)) {
309 |       const hp=this.screenPoint(Math.floor(hoverFloor.x),Math.floor(hoverFloor.y));
310 |       const T=TILE_SIZE*this.scale;
311 |       ctx.fillStyle=P.hoverTile; ctx.fillRect(hp.x,hp.y,T,T);
312 |       ctx.strokeStyle=P.hoverBorder; ctx.lineWidth=Math.max(1,Math.round(this.scale));
313 |       ctx.strokeRect(hp.x+.5,hp.y+.5,T-1,T-1);
314 |     }
315 |     this.hits=[];
316 |     const entries=OBJECTS.map(o=>({o,depth:o.y+o.d}));
317 |     entries.push({player:true,depth:founder.y+1});
318 |     entries.sort((a,b)=>a.depth-b.depth);
319 |     for(const entry of entries) {
320 |       if(entry.player) this.character(founder,moving,time);
321 |       else this.drawObject(entry.o,hovered);
322 |     }
323 |   }
324 | 
325 |   hitTest(sx,sy) {
326 |     const wp=this.floorPoint(sx,sy);
327 |     for(const o of [...this.hits].reverse()) {
328 |       if(wp.x>=o.x&&wp.x<o.x+o.w&&wp.y>=o.y&&wp.y<o.y+o.d) return o;
329 |     }
330 |     return null;
331 |   }
332 | }
