import { OBJECTS, ROOM, TILE_SIZE, project, unproject, isWalkable } from './world.js';

// ── Palette ──────────────────────────────────────────────────────────────────
const P = {
  // Floor – warm parquet
  plankA:'#c8a87a', plankB:'#be9e6e', plankC:'#d4b48a', plankGrain:'rgba(0,0,0,0.06)',
  // Walls
  wall:'#e8ddc8', wallBase:'#d4c8a8', skirting:'#b8a888', corner:'rgba(0,0,0,0.12)',
  // Wood furniture
  wood:'#a0784a', woodDark:'#7a5830', woodLight:'#c8a060', woodEdge:'#58381a',
  woodGrain:'rgba(255,255,255,0.06)',
  // Upholstery
  fabric:'#4a6898', fabricLight:'#6888b8', fabricDark:'#2a4878', fabricSeam:'rgba(0,0,0,0.18)',
  sofaMain:'#7a5840', sofaLight:'#9a7858', sofaDark:'#5a3828',
  // Screen / tech
  screen:'#0a1520', screenGlow:'#1a8ab8', screenLine:'#0a4a68', screenShine:'rgba(255,255,255,0.08)',
  keyRow:'rgba(255,255,255,0.07)', keyShadow:'rgba(0,0,0,0.4)',
  // Plant
  leafA:'#3a8a28', leafB:'#58a840', leafC:'#2a6818', leafShine:'rgba(255,255,255,0.22)',
  pot:'#c87848', potDark:'#985830', potRim:'#e09060', soil:'#3a2010',
  // Board / cork
  cork:'#c8a860', corkDark:'#a88840', noteY:'#f8e840', noteB:'#5898e8', noteG:'#58c858',
  boardPin:'#e84040',
  // Metal / cabinet
  metal:'#8a9898', metalDark:'#5a6868', metalLight:'#aababa', metalHandle:'#c8d8d8',
  // Character
  skin:'#e8b888', skinDark:'#c89060', skinShade:'rgba(0,0,0,0.15)',
  hair:'#2a1808', hairShine:'rgba(255,255,255,0.2)',
  shirt:'#3a6aaa', shirtDark:'#2a4a7a', shirtShine:'rgba(255,255,255,0.12)',
  pants:'#384858', pantsDark:'#283040',
  shoe:'#1a1008', shoeShine:'rgba(255,255,255,0.1)',
  eye:'#1a1208', eyeWhite:'#f8f0e8', eyeShine:'rgba(255,255,255,0.9)',
  // UI
  shadow:'rgba(0,0,0,0.22)',
  pathLine:'rgba(120,200,255,0.7)',
  hoverFill:'rgba(120,200,255,0.08)', hoverBorder:'rgba(100,180,255,0.5)',
  destMarker:'rgba(80,180,255,0.85)',
};

// ── Helpers ───────────────────────────────────────────────────────────────────
function rr(ctx, x, y, w, h, r) {
  r = Math.min(r, w / 2, h / 2);
  ctx.beginPath();
  ctx.roundRect(x, y, w, h, r);
}

function grad(ctx, x, y, w, h, c0, c1, vertical = true) {
  const g = vertical
    ? ctx.createLinearGradient(x, y, x, y + h)
    : ctx.createLinearGradient(x, y, x + w, y);
  g.addColorStop(0, c0); g.addColorStop(1, c1);
  return g;
}

function radGrad(ctx, cx, cy, r, c0, c1) {
  const g = ctx.createRadialGradient(cx, cy, 0, cx, cy, r);
  g.addColorStop(0, c0); g.addColorStop(1, c1);
  return g;
}

// ── Renderer ──────────────────────────────────────────────────────────────────
export class OfficeRenderer {
  constructor(canvas) {
    this.canvas = canvas;
    this.ctx = canvas.getContext('2d');
    this.width = 0; this.height = 0;
    this.zoom = 1; this.scale = 1;
    this.offset = { x: 0, y: 0 };
    this.hits = [];
    this.reducedMotion = matchMedia('(prefers-reduced-motion: reduce)').matches;
    this.resize();
  }

  resize() {
    const b = this.canvas.getBoundingClientRect();
    this.width = b.width; this.height = b.height;
    const dpr = Math.min(window.devicePixelRatio || 1, 2);
    this.canvas.width  = Math.round(b.width  * dpr);
    this.canvas.height = Math.round(b.height * dpr);
    this.dpr = dpr;
    this.updateCamera();
  }

  updateCamera() {
    const rw = ROOM.width  * TILE_SIZE;
    const rh = ROOM.depth  * TILE_SIZE;
    const raw = Math.min(this.width / rw, this.height / rh) * this.zoom;
    this.scale = Math.max(0.5, raw);           // fractional – smooth rendering
    this.offset = {
      x: Math.round((this.width  - rw * this.scale) / 2),
      y: Math.round((this.height - rh * this.scale) / 2),
    };
  }

  sp(tx, ty) {   // tile → screen
    const p = project(tx, ty);
    return { x: p.x * this.scale + this.offset.x,
             y: p.y * this.scale + this.offset.y };
  }

  floorPoint(sx, sy) {
    return unproject((sx - this.offset.x) / this.scale,
                     (sy - this.offset.y) / this.scale);
  }

  // ── Floor & walls ──────────────────────────────────────────────────────────
  floor() {
    const ctx = this.ctx, S = this.scale, T = TILE_SIZE * S;
    const tl = this.sp(0, 0);
    const W = ROOM.width * T, H = ROOM.depth * T;

    // Room background / wall colour
    ctx.fillStyle = P.wall;
    ctx.fillRect(tl.x - T * 2, tl.y - T * 3, W + T * 4, H + T * 4);

    // Floor planks – horizontal bands with alternating colour + grain
    const plankH = T * 0.5;
    const colors = [P.plankA, P.plankB, P.plankC, P.plankB];
    for (let ty = 0; ty < ROOM.depth; ty++) {
      const p = this.sp(0, ty);
      const ci = ty % colors.length;
      const g = grad(ctx, p.x, p.y, W, plankH * 2, colors[ci],
                     ci % 2 === 0 ? P.plankB : P.plankA);
      ctx.fillStyle = g;
      ctx.fillRect(p.x, p.y, W, T);
      // grain lines
      ctx.strokeStyle = P.plankGrain;
      ctx.lineWidth = 0.6;
      for (let i = 0; i < 3; i++) {
        const gy = p.y + T * (0.25 + i * 0.25);
        ctx.beginPath(); ctx.moveTo(p.x, gy); ctx.lineTo(p.x + W, gy); ctx.stroke();
      }
      // plank joints (vertical)
      ctx.strokeStyle = 'rgba(0,0,0,0.08)'; ctx.lineWidth = 0.8;
      const joints = Math.floor(ROOM.width / 2);
      for (let j = 1; j <= joints; j++) {
        const jx = p.x + (W / joints) * j;
        ctx.beginPath(); ctx.moveTo(jx, p.y); ctx.lineTo(jx, p.y + T); ctx.stroke();
      }
    }

    // Skirting board (baseboard)
    const sk = Math.max(4, S * 3);
    ctx.fillStyle = P.skirting;
    ctx.fillRect(tl.x - sk, tl.y, sk, H);               // left wall
    ctx.fillRect(tl.x, tl.y - sk * 2, W, sk * 2);       // top wall
    // Wall surface above floor
    ctx.fillStyle = P.wallBase;
    ctx.fillRect(tl.x, tl.y - T * 2.5, W, T * 2.5);

    // Corner AO shadows
    ctx.fillStyle = P.corner;
    ctx.fillRect(tl.x, tl.y, Math.max(8, S * 4), H);
    ctx.fillRect(tl.x, tl.y, W, Math.max(8, S * 4));

    // Outer border
    const bw = Math.max(2, S * 2);
    ctx.fillStyle = '#1a1210';
    ctx.fillRect(tl.x - sk - bw, tl.y - sk * 2 - bw, W + sk + bw * 2, bw);
    ctx.fillRect(tl.x - sk - bw, tl.y, bw, H);
    ctx.fillRect(tl.x - sk - bw, tl.y + H, W + sk + bw * 2, bw);
    ctx.fillRect(tl.x + W, tl.y - sk * 2 - bw, bw, H + sk * 2 + bw * 2);
  }

  // ── Object dispatcher ──────────────────────────────────────────────────────
  drawObject(obj, hovered) {
    this.hits.push(obj);
    const hot = hovered === obj.id;
    const S = this.scale, T = TILE_SIZE * S;
    const p = this.sp(obj.x, obj.y);
    const W = obj.w * T, H = obj.d * T;
    const ctx = this.ctx;

    // Drop shadow
    ctx.save();
    ctx.shadowColor = 'rgba(0,0,0,0.35)';
    ctx.shadowBlur = S * 6;
    ctx.shadowOffsetX = S * 2; ctx.shadowOffsetY = S * 3;
    ctx.fillStyle = 'transparent';
    rr(ctx, p.x, p.y, W, H, S * 2); ctx.fill();
    ctx.restore();

    switch (obj.type) {
      case 'plant':    this._plant(ctx, p, W, H, S, T, hot); break;
      case 'board':    this._board(ctx, p, W, H, S, T, hot); break;
      case 'cabinet':  this._cabinet(ctx, p, W, H, S, T, hot); break;
      case 'shelf':    this._shelf(ctx, p, W, H, S, T, hot, obj); break;
      case 'desk':     this._desk(ctx, p, W, H, S, T, hot); break;
      case 'desk-small': this._deskSmall(ctx, p, W, H, S, T, hot); break;
      case 'chair':    this._chair(ctx, p, W, H, S, T, hot); break;
      case 'sofa':     this._sofa(ctx, p, W, H, S, T, hot); break;
      case 'table':    this._table(ctx, p, W, H, S, T, hot); break;
      default:
        rr(ctx, p.x, p.y, W, H, S * 2);
        ctx.fillStyle = hot ? '#9a8a7a' : '#7a6a5a'; ctx.fill();
    }

    // Hover ring
    if (hot) {
      ctx.save();
      ctx.strokeStyle = 'rgba(120,200,255,0.7)';
      ctx.lineWidth = Math.max(1.5, S);
      ctx.shadowColor = 'rgba(80,160,255,0.5)'; ctx.shadowBlur = S * 8;
      rr(ctx, p.x - S, p.y - S, W + S * 2, H + S * 2, S * 3);
      ctx.stroke(); ctx.restore();
    }
  }

  // ── Plant ──────────────────────────────────────────────────────────────────
  _plant(ctx, p, W, H, S, T, hot) {
    const cx = p.x + W / 2, cy = p.y + H / 2;

    // Pot
    const potW = W * 0.52, potH = H * 0.34;
    const px = cx - potW / 2, py = p.y + H * 0.6;
    ctx.fillStyle = grad(ctx, px, py, potW, potH, P.potRim, P.potDark);
    rr(ctx, px, py, potW, potH, S * 2); ctx.fill();
    // Pot rim highlight
    ctx.fillStyle = P.pot;
    rr(ctx, px, py, potW, S * 2.5, S); ctx.fill();
    // Soil
    ctx.fillStyle = P.soil;
    rr(ctx, px + S, py + S, potW - S * 2, S * 2, S); ctx.fill();

    // Leaves (5 bezier teardrops radiating from stem)
    const stemX = cx, stemY = py - S * 2;
    const leafDefs = [
      { angle: -0.7, len: H * 0.42, col: P.leafA },
      { angle:  0.6, len: H * 0.38, col: P.leafB },
      { angle: -1.5, len: H * 0.3,  col: P.leafC },
      { angle:  1.4, len: H * 0.28, col: P.leafA },
      { angle: -0.1, len: H * 0.48, col: hot ? P.leafB : P.leafA },
    ];
    for (const lf of leafDefs) {
      const tx2 = stemX + Math.cos(lf.angle - Math.PI / 2) * lf.len;
      const ty2 = stemY + Math.sin(lf.angle - Math.PI / 2) * lf.len;
      const mx  = (stemX + tx2) / 2 + Math.cos(lf.angle) * lf.len * 0.4;
      const my  = (stemY + ty2) / 2 + Math.sin(lf.angle) * lf.len * 0.4;
      ctx.beginPath();
      ctx.moveTo(stemX, stemY);
      ctx.quadraticCurveTo(mx, my, tx2, ty2);
      ctx.quadraticCurveTo(mx - S * 3, my, stemX, stemY);
      ctx.fillStyle = lf.col; ctx.fill();
      // Leaf shine
      ctx.strokeStyle = P.leafShine; ctx.lineWidth = S * 0.6;
      ctx.beginPath();
      ctx.moveTo(stemX + (tx2 - stemX) * 0.15, stemY + (ty2 - stemY) * 0.15);
      ctx.quadraticCurveTo(mx, my, tx2 - (tx2 - stemX) * 0.1, ty2 - (ty2 - stemY) * 0.1);
      ctx.stroke();
    }
    // Stem
    ctx.strokeStyle = P.leafC; ctx.lineWidth = S * 1.2;
    ctx.beginPath(); ctx.moveTo(cx, py); ctx.lineTo(cx, stemY - S * 2); ctx.stroke();
  }

  // ── Whiteboard / corkboard ─────────────────────────────────────────────────
  _board(ctx, p, W, H, S, T, hot) {
    // Frame
    ctx.fillStyle = grad(ctx, p.x, p.y, W, H, '#6a5838', '#4a3820');
    rr(ctx, p.x, p.y, W, H, S * 2); ctx.fill();
    // Cork surface
    const pad = S * 3;
    ctx.fillStyle = hot ? '#d8b870' : P.cork;
    rr(ctx, p.x + pad, p.y + pad, W - pad * 2, H - pad * 2, S); ctx.fill();
    // Cork texture dots
    ctx.fillStyle = P.corkDark;
    for (let i = 0; i < 12; i++) {
      const nx = p.x + pad * 1.5 + ((i * 137) % (W - pad * 3));
      const ny = p.y + pad * 1.5 + ((i * 97)  % (H - pad * 3));
      ctx.beginPath(); ctx.arc(nx, ny, S * 0.6, 0, Math.PI * 2); ctx.fill();
    }
    // Sticky notes
    const notes = [
      { col: P.noteY, x: 0.08, y: 0.1,  nw: 0.28, nh: 0.35 },
      { col: P.noteB, x: 0.42, y: 0.08, nw: 0.24, nh: 0.30 },
      { col: P.noteG, x: 0.68, y: 0.15, nw: 0.22, nh: 0.28 },
      { col: P.noteY, x: 0.15, y: 0.55, nw: 0.26, nh: 0.32 },
    ];
    for (const n of notes) {
      const nx = p.x + pad + (W - pad * 2) * n.x;
      const ny = p.y + pad + (H - pad * 2) * n.y;
      const nw = (W - pad * 2) * n.nw, nh = (H - pad * 2) * n.nh;
      ctx.save();
      ctx.shadowColor = 'rgba(0,0,0,0.2)'; ctx.shadowBlur = S * 3;
      ctx.shadowOffsetX = S; ctx.shadowOffsetY = S;
      ctx.fillStyle = n.col;
      rr(ctx, nx, ny, nw, nh, S * 0.8); ctx.fill();
      ctx.restore();
      // lines on note
      ctx.strokeStyle = 'rgba(0,0,0,0.15)'; ctx.lineWidth = 0.8;
      for (let l = 0; l < 2; l++) {
        const ly = ny + nh * (0.35 + l * 0.28);
        ctx.beginPath(); ctx.moveTo(nx + nw * 0.12, ly); ctx.lineTo(nx + nw * 0.88, ly); ctx.stroke();
      }
    }
    // Push pins
    for (const n of notes) {
      const px2 = p.x + pad + (W - pad * 2) * (n.x + n.nw / 2);
      const py2 = p.y + pad + (H - pad * 2) * n.y;
      ctx.beginPath(); ctx.arc(px2, py2, S * 1.4, 0, Math.PI * 2);
      ctx.fillStyle = P.boardPin; ctx.fill();
      ctx.beginPath(); ctx.arc(px2 - S * 0.4, py2 - S * 0.4, S * 0.5, 0, Math.PI * 2);
      ctx.fillStyle = 'rgba(255,255,255,0.6)'; ctx.fill();
    }
    // Scrawled lines (ideas)
    ctx.strokeStyle = '#2a1808'; ctx.lineWidth = S * 0.9;
    ctx.beginPath();
    ctx.moveTo(p.x + W * 0.52, p.y + H * 0.55);
    ctx.bezierCurveTo(p.x + W * 0.6, p.y + H * 0.45, p.x + W * 0.75, p.y + H * 0.62, p.x + W * 0.82, p.y + H * 0.72);
    ctx.stroke();
  }

  // ── Filing cabinet ─────────────────────────────────────────────────────────
  _cabinet(ctx, p, W, H, S, T, hot) {
    // Body
    ctx.fillStyle = grad(ctx, p.x, p.y, W, H, hot ? P.metalLight : P.metal, P.metalDark);
    rr(ctx, p.x, p.y, W, H, S * 1.5); ctx.fill();
    // Top face (slight 3D)
    ctx.fillStyle = hot ? P.metalLight : '#9aabab';
    rr(ctx, p.x, p.y, W, S * 3, S); ctx.fill();
    // Drawers
    const drawers = Math.max(2, Math.round(obj_d_safe(H, T, 2)));
    const dh = (H - S * 4) / drawers;
    for (let d = 0; d < drawers; d++) {
      const dy = p.y + S * 2 + d * dh;
      // Drawer recess
      ctx.fillStyle = P.metalDark;
      rr(ctx, p.x + S * 2, dy + S, W - S * 4, dh - S * 2, S); ctx.fill();
      ctx.fillStyle = grad(ctx, p.x + S * 2, dy + S, W - S * 4, dh - S * 2, P.metal, P.metalDark);
      rr(ctx, p.x + S * 3, dy + S * 1.5, W - S * 6, dh - S * 4, S * 0.8); ctx.fill();
      // Handle
      const hx = p.x + W / 2 - S * 4;
      const hy = dy + dh / 2 - S;
      ctx.fillStyle = P.metalHandle;
      rr(ctx, hx, hy, S * 8, S * 2, S); ctx.fill();
      ctx.fillStyle = 'rgba(255,255,255,0.3)';
      rr(ctx, hx + S, hy, S * 6, S * 0.8, S * 0.4); ctx.fill();
      // Divider line
      if (d > 0) {
        ctx.strokeStyle = P.metalDark; ctx.lineWidth = 0.8;
        ctx.beginPath(); ctx.moveTo(p.x + S, dy); ctx.lineTo(p.x + W - S, dy); ctx.stroke();
      }
    }
    // Edge highlight
    ctx.strokeStyle = 'rgba(255,255,255,0.15)'; ctx.lineWidth = S * 0.8;
    ctx.beginPath(); ctx.moveTo(p.x + S, p.y + S * 2); ctx.lineTo(p.x + S, p.y + H - S); ctx.stroke();
  }

  // ── Bookshelf ──────────────────────────────────────────────────────────────
  _shelf(ctx, p, W, H, S, T, hot, obj) {
    // Back panel
    ctx.fillStyle = P.woodDark;
    rr(ctx, p.x, p.y, W, H, S); ctx.fill();
    // Side panels
    ctx.fillStyle = grad(ctx, p.x, p.y, S * 3, H, P.woodLight, P.wood);
    ctx.fillRect(p.x, p.y, S * 3, H);
    ctx.fillStyle = grad(ctx, p.x + W - S * 3, p.y, S * 3, H, P.wood, P.woodDark);
    ctx.fillRect(p.x + W - S * 3, p.y, S * 3, H);

    const shelves = 3;
    const shH = H / shelves;
    const bookColors = ['#c04028','#4870b8','#e8a028','#48a840','#8840a8','#e84870','#38a8a8','#c87830'];
    let bci = 0;
    for (let s = 0; s < shelves; s++) {
      const sy = p.y + s * shH;
      const innerW = W - S * 6, innerX = p.x + S * 3;
      // Shelf plank
      ctx.fillStyle = grad(ctx, innerX, sy, innerW, S * 2.5, P.woodLight, P.wood);
      ctx.fillRect(innerX, sy, innerW, S * 2.5);
      // Books
      let bx = innerX + S;
      const zone = shH - S * 4;
      const maxBH = zone * 0.9;
      while (bx < innerX + innerW - S * 4) {
        const bw = S * (3 + ((bci * 7 + s * 3) % 4));
        const bh = maxBH * (0.6 + ((bci * 13 + s) % 5) * 0.08);
        const by = sy + S * 2.5 + (maxBH - bh);
        const tilt = ((bci * 5) % 3 === 0) ? ((bci % 2 ? 1 : -1) * 0.06) : 0;
        ctx.save();
        ctx.translate(bx + bw / 2, by + bh / 2);
        ctx.rotate(tilt);
        ctx.fillStyle = bookColors[bci % bookColors.length];
        rr(ctx, -bw / 2, -bh / 2, bw, bh, S * 0.4); ctx.fill();
        // Spine highlight
        ctx.fillStyle = 'rgba(255,255,255,0.18)';
        ctx.fillRect(-bw / 2 + S * 0.3, -bh / 2 + S, S * 0.8, bh * 0.6);
        // Page edge
        ctx.fillStyle = '#e8e0d0';
        ctx.fillRect(bw / 2 - S * 0.8, -bh / 2, S * 0.8, bh);
        ctx.restore();
        bx += bw + S * 0.5;
        bci++;
      }
    }
    // Top surface highlight
    ctx.fillStyle = hot ? P.woodLight : 'rgba(255,255,255,0.06)';
    ctx.fillRect(p.x + S * 3, p.y, W - S * 6, S * 1.5);
  }

  // ── Main desk ─────────────────────────────────────────────────────────────
  _desk(ctx, p, W, H, S, T, hot) {
    // Desk surface
    ctx.fillStyle = grad(ctx, p.x, p.y, W, H, hot ? P.woodLight : '#b88850', P.wood);
    rr(ctx, p.x, p.y, W, H, S * 2); ctx.fill();
    ctx.fillStyle = P.woodEdge;
    ctx.lineWidth = S * 1.5; ctx.strokeStyle = P.woodEdge;
    rr(ctx, p.x, p.y, W, H, S * 2); ctx.stroke();

    // Wood grain lines
    ctx.strokeStyle = P.woodGrain; ctx.lineWidth = 0.7;
    for (let g = 0; g < 4; g++) {
      const gx = p.x + W * (0.1 + g * 0.22);
      ctx.beginPath(); ctx.moveTo(gx, p.y + S); ctx.lineTo(gx, p.y + H - S); ctx.stroke();
    }

    // Monitor
    const mW = W * 0.42, mH = H * 0.56;
    const mx = p.x + W * 0.32, my = p.y + H * 0.08;
    // Bezel
    ctx.fillStyle = '#1a1a28';
    rr(ctx, mx, my, mW, mH, S * 1.5); ctx.fill();
    // Screen
    const sp2 = S * 1.5;
    ctx.fillStyle = P.screen;
    rr(ctx, mx + sp2, my + sp2, mW - sp2 * 2, mH - sp2 * 2 - S * 3, S); ctx.fill();
    // Screen glow
    const sg = ctx.createLinearGradient(mx + sp2, my + sp2, mx + sp2, my + mH - sp2 * 2);
    sg.addColorStop(0, P.screenGlow); sg.addColorStop(0.4, '#0a4060'); sg.addColorStop(1, '#050d15');
    ctx.fillStyle = sg;
    rr(ctx, mx + sp2, my + sp2, mW - sp2 * 2, mH - sp2 * 2 - S * 3, S); ctx.fill();
    // Code lines on screen
    ctx.strokeStyle = P.screenLine; ctx.lineWidth = S * 0.8;
    for (let l = 0; l < 4; l++) {
      const lw = (mW - sp2 * 2) * (0.4 + ((l * 37) % 5) * 0.1);
      const ly = my + sp2 * 2 + l * S * 3.5;
      if (ly + S < my + mH - sp2 * 3) {
        ctx.beginPath(); ctx.moveTo(mx + sp2 * 1.5, ly); ctx.lineTo(mx + sp2 * 1.5 + lw, ly); ctx.stroke();
      }
    }
    // Screen shine
    ctx.fillStyle = P.screenShine;
    rr(ctx, mx + sp2, my + sp2, mW - sp2 * 2, S * 2.5, S); ctx.fill();
    // Monitor stand
    const standW = mW * 0.25, standH = S * 2.5;
    ctx.fillStyle = '#282838';
    ctx.fillRect(mx + (mW - standW) / 2, my + mH - S * 3, standW, standH);
    ctx.fillStyle = '#3a3a4a';
    rr(ctx, mx + (mW - standW * 1.6) / 2, my + mH - S, standW * 1.6, S * 1.5, S * 0.5); ctx.fill();

    // Keyboard
    const kW = W * 0.38, kH = H * 0.14;
    const kx = p.x + W * 0.31, ky = p.y + H * 0.7;
    ctx.fillStyle = '#d8d0c0';
    rr(ctx, kx, ky, kW, kH, S * 0.8); ctx.fill();
    ctx.fillStyle = P.keyRow;
    // Key rows
    for (let r = 0; r < 3; r++) {
      ctx.fillRect(kx + S, ky + S + r * (kH / 3.2), kW - S * 2, kH / 3.5);
    }
    ctx.strokeStyle = 'rgba(0,0,0,0.12)'; ctx.lineWidth = 0.5;
    rr(ctx, kx, ky, kW, kH, S * 0.8); ctx.stroke();

    // Mouse
    const mouseX = p.x + W * 0.77, mouseY = p.y + H * 0.62;
    ctx.fillStyle = '#d8d0c0';
    ctx.beginPath();
    ctx.ellipse(mouseX, mouseY, S * 2.5, S * 3.5, 0, 0, Math.PI * 2); ctx.fill();
    ctx.strokeStyle = 'rgba(0,0,0,0.12)'; ctx.lineWidth = 0.6;
    ctx.beginPath();
    ctx.moveTo(mouseX, mouseY - S * 3.5); ctx.lineTo(mouseX, mouseY + S); ctx.stroke();

    // Coffee mug
    const mugX = p.x + W * 0.12, mugY = p.y + H * 0.25;
    const mugR = S * 3.2;
    ctx.fillStyle = '#c03820';
    ctx.beginPath(); ctx.ellipse(mugX, mugY, mugR, mugR * 0.7, 0, 0, Math.PI * 2); ctx.fill();
    ctx.fillStyle = '#e84828';
    ctx.beginPath(); ctx.ellipse(mugX, mugY - mugR * 0.1, mugR * 0.8, mugR * 0.5, 0, 0, Math.PI * 2); ctx.fill();
    ctx.strokeStyle = '#c03820'; ctx.lineWidth = S * 1.2;
    ctx.beginPath(); ctx.arc(mugX + mugR, mugY, mugR * 0.55, -0.6, 0.6); ctx.stroke();
    // steam
    if (!this.reducedMotion) {
      ctx.strokeStyle = 'rgba(200,200,200,0.3)'; ctx.lineWidth = S * 0.8;
      ctx.setLineDash([S * 1.2, S * 1.5]); ctx.lineDashOffset = -(this._time || 0) / 600;
      ctx.beginPath(); ctx.moveTo(mugX - S, mugY - mugR * 0.8); ctx.lineTo(mugX, mugY - mugR * 2); ctx.stroke();
      ctx.beginPath(); ctx.moveTo(mugX + S, mugY - mugR * 0.8); ctx.lineTo(mugX, mugY - mugR * 1.8); ctx.stroke();
      ctx.setLineDash([]);
    }
  }

  // ── Side desk ─────────────────────────────────────────────────────────────
  _deskSmall(ctx, p, W, H, S, T, hot) {
    ctx.fillStyle = grad(ctx, p.x, p.y, W, H, hot ? P.woodLight : '#c09058', P.wood);
    rr(ctx, p.x, p.y, W, H, S * 2); ctx.fill();
    ctx.strokeStyle = P.woodEdge; ctx.lineWidth = S * 1.2;
    rr(ctx, p.x, p.y, W, H, S * 2); ctx.stroke();

    // Notebook / sketchpad
    const nW = W * 0.45, nH = H * 0.6;
    const nx = p.x + W * 0.1, ny = p.y + H * 0.2;
    ctx.fillStyle = '#f0ead8';
    rr(ctx, nx, ny, nW, nH, S); ctx.fill();
    ctx.strokeStyle = 'rgba(0,0,0,0.1)'; ctx.lineWidth = 0.6;
    for (let l = 0; l < 4; l++) {
      const ly = ny + nH * (0.22 + l * 0.18);
      ctx.beginPath(); ctx.moveTo(nx + nW * 0.1, ly); ctx.lineTo(nx + nW * 0.9, ly); ctx.stroke();
    }
    // Spiral binding
    ctx.strokeStyle = '#aaa898'; ctx.lineWidth = S * 0.8;
    for (let h = 0; h < 5; h++) {
      const hy = ny + nH * (0.1 + h * 0.18);
      ctx.beginPath(); ctx.arc(nx - S * 0.5, hy, S * 1.2, 0, Math.PI * 2); ctx.stroke();
    }

    // Pen
    const penX1 = p.x + W * 0.62, penY1 = p.y + H * 0.18;
    const penX2 = p.x + W * 0.75, penY2 = p.y + H * 0.78;
    ctx.strokeStyle = '#3050a8'; ctx.lineWidth = S * 1.8;
    ctx.lineCap = 'round';
    ctx.beginPath(); ctx.moveTo(penX1, penY1); ctx.lineTo(penX2, penY2); ctx.stroke();
    ctx.strokeStyle = '#c0c0c0'; ctx.lineWidth = S * 1.8;
    ctx.beginPath(); ctx.moveTo(penX1, penY1); ctx.lineTo(penX1 + (penX2-penX1)*0.15, penY1 + (penY2-penY1)*0.15); ctx.stroke();
    ctx.lineCap = 'butt';
  }

  // ── Chair ─────────────────────────────────────────────────────────────────
  _chair(ctx, p, W, H, S, T, hot) {
    const cx = p.x + W / 2, cy = p.y + H / 2;

    // 5-point base (star) + casters
    ctx.strokeStyle = '#282838'; ctx.lineWidth = S * 1.4;
    for (let i = 0; i < 5; i++) {
      const a = (i / 5) * Math.PI * 2 - Math.PI / 2;
      const r = W * 0.38;
      const ex = cx + Math.cos(a) * r, ey = cy + H * 0.4 + Math.sin(a) * r * 0.5;
      ctx.beginPath(); ctx.moveTo(cx, cy + H * 0.38); ctx.lineTo(ex, ey); ctx.stroke();
      // Caster
      ctx.fillStyle = '#383848';
      ctx.beginPath(); ctx.arc(ex, ey, S * 1.5, 0, Math.PI * 2); ctx.fill();
    }
    // Center column
    ctx.fillStyle = grad(ctx, cx - S * 1.5, cy, S * 3, H * 0.4, '#484858', '#282838');
    ctx.fillRect(cx - S * 1.5, cy, S * 3, H * 0.38);

    // Seat cushion
    const seatW = W * 0.78, seatH = H * 0.38;
    ctx.fillStyle = grad(ctx, cx - seatW/2, cy - seatH*0.6, seatW, seatH, hot ? P.fabricLight : P.fabric, P.fabricDark);
    ctx.beginPath();
    ctx.ellipse(cx, cy - seatH * 0.05, seatW / 2, seatH / 2, 0, 0, Math.PI * 2);
    ctx.fill();
    // Seat seam
    ctx.strokeStyle = P.fabricSeam; ctx.lineWidth = S * 0.7;
    ctx.beginPath();
    ctx.ellipse(cx, cy - seatH * 0.05, seatW * 0.6 / 2, seatH * 0.6 / 2, 0, 0, Math.PI * 2);
    ctx.stroke();
    // Seat shine
    ctx.fillStyle = 'rgba(255,255,255,0.1)';
    ctx.beginPath();
    ctx.ellipse(cx - seatW * 0.1, cy - seatH * 0.2, seatW * 0.25, seatH * 0.18, -0.3, 0, Math.PI * 2);
    ctx.fill();

    // Backrest
    const bW = W * 0.62, bH = H * 0.38;
    const bx = cx - bW / 2, by = p.y + S;
    ctx.fillStyle = grad(ctx, bx, by, bW, bH, hot ? P.fabricLight : P.fabric, P.fabricDark);
    rr(ctx, bx, by, bW, bH, S * 3); ctx.fill();
    // Backrest seam
    ctx.strokeStyle = P.fabricSeam; ctx.lineWidth = S * 0.7;
    rr(ctx, bx + S * 2, by + S * 2, bW - S * 4, bH - S * 4, S * 2); ctx.stroke();
    // Backrest shine
    ctx.fillStyle = 'rgba(255,255,255,0.09)';
    rr(ctx, bx + S * 2, by + S * 1.5, bW - S * 4, bH * 0.3, S * 2); ctx.fill();

    // Armrests
    for (const side of [-1, 1]) {
      const arx = cx + side * (seatW / 2 + S) - S * 1.5;
      const ary = cy - seatH * 0.5;
      ctx.fillStyle = '#383848';
      rr(ctx, arx, ary, S * 3, S * 5, S); ctx.fill();
    }
  }

  // ── Sofa ───────────────────────────────────────────────────────────────────
  _sofa(ctx, p, W, H, S, T, hot) {
    // Body
    ctx.fillStyle = grad(ctx, p.x, p.y, W, H, hot ? P.sofaLight : P.sofaMain, P.sofaDark);
    rr(ctx, p.x, p.y, W, H, S * 3); ctx.fill();

    // Backrest
    const bkH = H * 0.32;
    ctx.fillStyle = grad(ctx, p.x, p.y, W, bkH, hot ? '#b89070' : P.sofaLight, P.sofaMain);
    rr(ctx, p.x, p.y, W, bkH, S * 3); ctx.fill();
    // Backrest seam
    ctx.strokeStyle = 'rgba(0,0,0,0.15)'; ctx.lineWidth = S * 0.7;
    rr(ctx, p.x + S * 2, p.y + S * 2, W - S * 4, bkH - S * 4, S * 2); ctx.stroke();

    // Seat cushions (2 side by side)
    const cW = (W - S * 6) / 2, cH = H * 0.5;
    const cY = p.y + bkH;
    for (let i = 0; i < 2; i++) {
      const cx2 = p.x + S * 3 + i * (cW + S * 0);
      ctx.fillStyle = grad(ctx, cx2, cY, cW, cH, hot ? P.sofaLight : '#9a7858', P.sofaDark);
      rr(ctx, cx2, cY, cW, cH, S * 2); ctx.fill();
      // Cushion seam
      ctx.strokeStyle = 'rgba(0,0,0,0.12)'; ctx.lineWidth = S * 0.7;
      rr(ctx, cx2 + S * 2, cY + S * 2, cW - S * 4, cH - S * 4, S); ctx.stroke();
      // Cushion shine
      ctx.fillStyle = 'rgba(255,255,255,0.08)';
      rr(ctx, cx2 + S * 2, cY + S * 1.5, cW - S * 4, cH * 0.2, S); ctx.fill();
    }
    // Divider between cushions
    ctx.fillStyle = P.sofaDark;
    ctx.fillRect(p.x + W / 2 - S * 0.8, cY, S * 1.6, cH);

    // Armrests
    for (const side of [0, 1]) {
      const arX = side === 0 ? p.x : p.x + W - S * 4;
      ctx.fillStyle = grad(ctx, arX, p.y, S * 4, H, hot ? P.sofaLight : P.sofaMain, P.sofaDark);
      rr(ctx, arX, p.y, S * 4, H, S * 2); ctx.fill();
    }

    // Throw pillow
    const piW = W * 0.18, piH = H * 0.24;
    const piX = p.x + W * 0.56, piY = p.y + bkH + S;
    ctx.save();
    ctx.shadowColor = 'rgba(0,0,0,0.2)'; ctx.shadowBlur = S * 3;
    ctx.fillStyle = '#e87040';
    rr(ctx, piX, piY, piW, piH, S * 2); ctx.fill();
    ctx.restore();
    ctx.strokeStyle = 'rgba(255,255,255,0.2)'; ctx.lineWidth = S * 0.7;
    ctx.beginPath(); ctx.moveTo(piX + piW / 2, piY + S); ctx.lineTo(piX + piW / 2, piY + piH - S); ctx.stroke();
    ctx.beginPath(); ctx.moveTo(piX + S, piY + piH / 2); ctx.lineTo(piX + piW - S, piY + piH / 2); ctx.stroke();
  }

  // ── Coffee table ──────────────────────────────────────────────────────────
  _table(ctx, p, W, H, S, T, hot) {
    // Legs
    const legR = S * 1.8;
    for (const [lx, ly] of [[0.1, 0.15], [0.9, 0.15], [0.1, 0.85], [0.9, 0.85]]) {
      ctx.fillStyle = P.woodDark;
      ctx.beginPath(); ctx.ellipse(p.x + W * lx, p.y + H * ly, legR, legR * 0.7, 0, 0, Math.PI * 2); ctx.fill();
    }
    // Table top
    ctx.fillStyle = grad(ctx, p.x, p.y + H * 0.05, W, H * 0.8, hot ? P.woodLight : '#c09458', P.wood);
    rr(ctx, p.x + S, p.y + H * 0.08, W - S * 2, H * 0.75, S * 2); ctx.fill();
    ctx.strokeStyle = P.woodEdge; ctx.lineWidth = S * 0.8;
    rr(ctx, p.x + S, p.y + H * 0.08, W - S * 2, H * 0.75, S * 2); ctx.stroke();
    // Wood grain
    ctx.strokeStyle = P.woodGrain; ctx.lineWidth = 0.6;
    for (let g = 0; g < 3; g++) {
      ctx.beginPath();
      ctx.moveTo(p.x + S * 2 + g * (W / 3.5), p.y + H * 0.1);
      ctx.lineTo(p.x + S * 2 + g * (W / 3.5), p.y + H * 0.8); ctx.stroke();
    }
    // Two coffee mugs / glasses
    for (const [gx, gy, col] of [[0.28, 0.38, '#e84040'], [0.65, 0.36, '#4080e8']]) {
      const gW = S * 3.5, gH = S * 5;
      const gPx = p.x + W * gx, gPy = p.y + H * gy;
      ctx.fillStyle = col;
      rr(ctx, gPx, gPy, gW, gH, S * 0.8); ctx.fill();
      // Liquid
      ctx.fillStyle = 'rgba(255,255,255,0.15)';
      rr(ctx, gPx, gPy, gW, gH * 0.25, S * 0.6); ctx.fill();
    }
  }

  // ── Character ─────────────────────────────────────────────────────────────
  character(founder, dir, moving, time) {
    this._time = time;
    const S = this.scale, T = TILE_SIZE * S;
    const p = this.sp(founder.x, founder.y);
    const cx = p.x + T / 2, cy = p.y + T * 0.55;
    const ctx = this.ctx;

    const frame = (moving && !this.reducedMotion) ? Math.floor(time / 140) % 4 : 0;
    const bob   = (moving && !this.reducedMotion) ? Math.sin(time / 140 * Math.PI) * S * 0.8 : 0;
    const u = S * 1.1;   // base unit – fractional for smooth

    // Ground shadow
    ctx.fillStyle = 'rgba(0,0,0,0.18)';
    ctx.beginPath();
    ctx.ellipse(cx, cy + u * 7, u * 5, u * 1.8, 0, 0, Math.PI * 2); ctx.fill();

    const bodyY = cy - bob;

    // ── Legs (direction-aware, 4-frame walk cycle) ──
    const legSwing = Math.sin(time / 140 * Math.PI);
    const legFwd = moving ? legSwing * u * 3 : 0;

    for (const [side, sign] of [['left', -1], ['right', 1]]) {
      const legOff = side === 'left' ? -legFwd : legFwd;
      // Shoe
      ctx.fillStyle = grad(ctx, cx + sign * u * 1.5 - u * 2, bodyY + u * 6 + legOff,
                           u * 4.5, u * 2.5, '#2a2018', P.shoe);
      ctx.beginPath();
      ctx.ellipse(cx + sign * u * 1.8, bodyY + u * 8 + legOff, u * 2.5, u * 1.4, 0, 0, Math.PI * 2);
      ctx.fill();
      ctx.fillStyle = P.shoeShine;
      ctx.beginPath();
      ctx.ellipse(cx + sign * u * 1.2, bodyY + u * 7.3 + legOff, u * 1.2, u * 0.7, -0.3, 0, Math.PI * 2);
      ctx.fill();
      // Pant leg
      ctx.fillStyle = side === 'left' ? P.pants : P.pantsDark;
      rr(ctx, cx + sign * u * 0.5, bodyY + u * 2.5, u * 2.8, u * 5.5 + legOff * (sign > 0 ? 1 : -1) * 0.3, u * 1.2);
      ctx.fill();
    }

    // ── Torso ──
    const torsoGrad = grad(ctx, cx - u * 4, bodyY - u * 6, u * 8, u * 9, P.shirt, P.shirtDark);
    ctx.fillStyle = torsoGrad;
    rr(ctx, cx - u * 4, bodyY - u * 6, u * 8, u * 8.5, u * 2); ctx.fill();
    // Shirt collar detail
    ctx.fillStyle = P.shirtShine;
    rr(ctx, cx - u * 3.5, bodyY - u * 6, u * 7, u * 2.5, u * 2); ctx.fill();
    // Shirt button line
    ctx.strokeStyle = 'rgba(255,255,255,0.1)'; ctx.lineWidth = u * 0.6;
    ctx.beginPath(); ctx.moveTo(cx, bodyY - u * 5.5); ctx.lineTo(cx, bodyY + u * 2); ctx.stroke();

    // ── Arms ──
    const armSwing = moving ? legSwing * u * 2.5 : 0;
    for (const [sign, swing] of [[-1, armSwing], [1, -armSwing]]) {
      ctx.fillStyle = P.shirt;
      rr(ctx, cx + sign * u * 4, bodyY - u * 5 + swing, u * 2.8, u * 6, u * 1.4); ctx.fill();
      // Hand
      ctx.fillStyle = P.skin;
      ctx.beginPath();
      ctx.ellipse(cx + sign * u * 5.4, bodyY + u * 2 + swing, u * 1.8, u * 2, 0.2 * sign, 0, Math.PI * 2);
      ctx.fill();
    }

    // ── Neck ──
    ctx.fillStyle = P.skinDark;
    rr(ctx, cx - u * 1.4, bodyY - u * 7.5, u * 2.8, u * 2, u * 1.2); ctx.fill();

    // ── Head ──
    const headGrad = radGrad(ctx, cx - u * 0.8, bodyY - u * 12, u * 4, P.skin, P.skinDark);
    ctx.fillStyle = headGrad;
    ctx.beginPath();
    ctx.ellipse(cx, bodyY - u * 11.5, u * 4.2, u * 4.8, 0, 0, Math.PI * 2); ctx.fill();
    // Face shadow underplane
    ctx.fillStyle = P.skinShade;
    ctx.beginPath();
    ctx.ellipse(cx, bodyY - u * 9.5, u * 3.5, u * 1.8, 0, 0, Math.PI); ctx.fill();

    // ── Hair ──
    ctx.fillStyle = P.hair;
    ctx.beginPath();
    ctx.ellipse(cx, bodyY - u * 14.2, u * 4.2, u * 2.2, 0, Math.PI, Math.PI * 2); ctx.fill();
    // Side hair
    ctx.beginPath();
    ctx.ellipse(cx - u * 4, bodyY - u * 12, u * 1.2, u * 2.5, 0.3, 0, Math.PI * 2); ctx.fill();
    ctx.beginPath();
    ctx.ellipse(cx + u * 4, bodyY - u * 12, u * 1.2, u * 2.5, -0.3, 0, Math.PI * 2); ctx.fill();
    // Hair shine
    ctx.fillStyle = P.hairShine;
    ctx.beginPath();
    ctx.ellipse(cx - u * 1, bodyY - u * 14, u * 1.8, u * 1, -0.3, 0, Math.PI * 2); ctx.fill();

    // ── Eyes ──
    for (const [sx, brow] of [[-1.8, -0.15], [1.8, 0.15]]) {
      const ex = cx + u * sx, ey = bodyY - u * 12;
      // Eye white
      ctx.fillStyle = P.eyeWhite;
      ctx.beginPath(); ctx.ellipse(ex, ey, u * 1.5, u * 1.1, brow * 0.2, 0, Math.PI * 2); ctx.fill();
      // Iris
      ctx.fillStyle = '#4878c8';
      ctx.beginPath(); ctx.ellipse(ex + u * 0.1, ey, u * 0.9, u * 1.0, 0, 0, Math.PI * 2); ctx.fill();
      // Pupil
      ctx.fillStyle = P.eye;
      ctx.beginPath(); ctx.ellipse(ex + u * 0.15, ey, u * 0.55, u * 0.6, 0, 0, Math.PI * 2); ctx.fill();
      // Shine
      ctx.fillStyle = P.eyeShine;
      ctx.beginPath(); ctx.arc(ex + u * 0.4, ey - u * 0.4, u * 0.32, 0, Math.PI * 2); ctx.fill();
      // Eyebrow
      ctx.strokeStyle = P.hair; ctx.lineWidth = u * 0.9;
      ctx.lineCap = 'round';
      ctx.beginPath();
      ctx.moveTo(ex - u * 1.2, ey - u * 1.6 + brow * u);
      ctx.lineTo(ex + u * 1.2, ey - u * 1.5 - brow * u);
      ctx.stroke(); ctx.lineCap = 'butt';
    }

    // ── Mouth (slight smile) ──
    ctx.strokeStyle = P.skinDark; ctx.lineWidth = u * 0.7;
    ctx.lineCap = 'round';
    ctx.beginPath();
    ctx.moveTo(cx - u * 1.4, bodyY - u * 10.2);
    ctx.quadraticCurveTo(cx, bodyY - u * 9.6, cx + u * 1.4, bodyY - u * 10.2);
    ctx.stroke(); ctx.lineCap = 'butt';

    // ── Name tag ──
    ctx.save();
    const tagY = bodyY - u * 18;
    ctx.font = `bold ${Math.max(8, S * 5.5)}px 'Courier New', monospace`;
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    const label = 'ALEX';
    const tw = ctx.measureText(label).width + S * 8;
    const th = S * 7;
    // Tag background
    rr(ctx, cx - tw / 2, tagY - th / 2, tw, th, S * 1.5);
    ctx.fillStyle = 'rgba(10,15,20,0.7)'; ctx.fill();
    ctx.strokeStyle = 'rgba(80,160,255,0.5)'; ctx.lineWidth = S * 0.8;
    rr(ctx, cx - tw / 2, tagY - th / 2, tw, th, S * 1.5); ctx.stroke();
    // Tag text
    ctx.fillStyle = '#a8d8ff';
    ctx.fillText(label, cx, tagY);
    ctx.restore();
  }

  // ── Path overlay ──────────────────────────────────────────────────────────
  drawPath(pathArr, founder, time) {
    if (!pathArr.length) return;
    const ctx = this.ctx, S = this.scale, T = TILE_SIZE * S;

    ctx.save();
    ctx.lineCap = 'round'; ctx.lineJoin = 'round';
    ctx.setLineDash([S * 4, S * 5]);
    ctx.lineDashOffset = this.reducedMotion ? 0 : -(time / 60);
    ctx.strokeStyle = P.pathLine;
    ctx.lineWidth = Math.max(1.5, S * 1.5);
    ctx.shadowColor = 'rgba(80,160,255,0.4)'; ctx.shadowBlur = S * 4;

    ctx.beginPath();
    const sp = this.sp(founder.x, founder.y);
    ctx.moveTo(sp.x + T / 2, sp.y + T / 2);
    for (const wp of pathArr) {
      const pp = this.sp(wp.x, wp.y);
      ctx.lineTo(pp.x + T / 2, pp.y + T / 2);
    }
    ctx.stroke();
    ctx.restore();

    // Destination marker – animated ring
    const last = pathArr[pathArr.length - 1];
    const lp = this.sp(last.x, last.y);
    const lx = lp.x + T / 2, ly = lp.y + T / 2;
    const pulse = this.reducedMotion ? 1 : 0.5 + Math.sin(time / 200) * 0.5;
    const outerR = S * 6 + (this.reducedMotion ? 0 : Math.sin(time / 400) * S * 2);
    ctx.save();
    ctx.strokeStyle = `rgba(80,180,255,${pulse})`;
    ctx.lineWidth = Math.max(1, S);
    ctx.shadowColor = 'rgba(80,160,255,0.6)'; ctx.shadowBlur = S * 8;
    ctx.beginPath(); ctx.arc(lx, ly, outerR, 0, Math.PI * 2); ctx.stroke();
    ctx.strokeStyle = `rgba(160,220,255,${pulse * 0.7})`;
    ctx.lineWidth = S * 0.6;
    ctx.beginPath(); ctx.arc(lx, ly, outerR * 0.5, 0, Math.PI * 2); ctx.stroke();
    ctx.restore();
  }

  // ── Main render ───────────────────────────────────────────────────────────
  render({ founder, path, hovered, hoverFloor, direction, moving, time }) {
    const ctx = this.ctx;
    this._time = time;
    ctx.imageSmoothingEnabled = true;
    ctx.imageSmoothingQuality = 'high';
    ctx.setTransform(this.dpr, 0, 0, this.dpr, 0, 0);
    ctx.fillStyle = '#18120c';
    ctx.fillRect(0, 0, this.width, this.height);

    this.floor();
    this.drawPath(path, founder, time);

    // Hover tile highlight
    if (hoverFloor && !hovered && isWalkable(hoverFloor.x, hoverFloor.y)) {
      const T = TILE_SIZE * this.scale;
      const hp = this.sp(Math.floor(hoverFloor.x), Math.floor(hoverFloor.y));
      ctx.fillStyle = P.hoverFill;
      rr(ctx, hp.x, hp.y, T, T, this.scale); ctx.fill();
      ctx.strokeStyle = P.hoverBorder;
      ctx.lineWidth = Math.max(1, this.scale * 0.8);
      ctx.shadowColor = 'rgba(80,160,255,0.3)'; ctx.shadowBlur = this.scale * 4;
      rr(ctx, hp.x, hp.y, T, T, this.scale); ctx.stroke();
      ctx.shadowBlur = 0;
    }

    // Sort objects + player by depth
    this.hits = [];
    const entries = OBJECTS.map(o => ({ o, depth: o.y + o.d }));
    entries.push({ player: true, depth: founder.y + 1 });
    entries.sort((a, b) => a.depth - b.depth);

    for (const entry of entries) {
      if (entry.player) this.character(founder, direction, moving, time);
      else this.drawObject(entry.o, hovered);
    }
  }

  hitTest(sx, sy) {
    const wp = this.floorPoint(sx, sy);
    for (const o of [...this.hits].reverse()) {
      if (wp.x >= o.x && wp.x < o.x + o.w && wp.y >= o.y && wp.y < o.y + o.d) return o;
    }
    return null;
  }
}

// ── Internal helper (avoids 'obj' closure in switch) ────────────────────────
function obj_d_safe(H, T, fallback) { return H / T || fallback; }

