PART5 = r"""
  character(founder, dir, moving, time) {
    this._time = time;
    const S=this.scale, T=TILE_SIZE*S;
    const p=this.sp(founder.x,founder.y);
    const cx=p.x+T/2, cy=p.y+T*0.55;
    const ctx=this.ctx;
    const bob=(moving&&!this.reducedMotion)?Math.sin(time/140*Math.PI)*S*0.8:0;
    const u=S*1.1;
    const bodyY=cy-bob;

    // Ground shadow
    ctx.fillStyle='rgba(0,0,0,0.15)';
    ctx.beginPath(); ctx.ellipse(cx,cy+u*6.5,u*5,u*1.8,0,0,Math.PI*2); ctx.fill();

    // Legs
    const legSwing=(moving&&!this.reducedMotion)?Math.sin(time/140*Math.PI):0;
    for (const [sign,swing] of [[-1,legSwing],[1,-legSwing]]) {
      const legOff=swing*u*2.5;
      // Shoe
      ctx.fillStyle=grad(ctx,cx+sign*u*1.5-u*2,bodyY+u*6+legOff,u*4.5,u*2.5,'#2a2018',P.shoe);
      ctx.beginPath(); ctx.ellipse(cx+sign*u*1.8,bodyY+u*7.8+legOff,u*2.5,u*1.4,0,0,Math.PI*2); ctx.fill();
      ctx.fillStyle=P.shoeShine;
      ctx.beginPath(); ctx.ellipse(cx+sign*u*1.2,bodyY+u*7.1+legOff,u*1.2,u*0.7,-0.3,0,Math.PI*2); ctx.fill();
      // Pants
      ctx.fillStyle=sign<0?P.pants:P.pantsDark;
      rr(ctx,cx+sign*u*0.5,bodyY+u*2.5,u*2.8,u*5.3+Math.abs(legOff)*0.2,u*1.2); ctx.fill();
    }

    // Torso
    ctx.fillStyle=grad(ctx,cx-u*4,bodyY-u*6,u*8,u*9,P.shirt,P.shirtDark);
    rr(ctx,cx-u*4,bodyY-u*6,u*8,u*8.5,u*2); ctx.fill();
    ctx.fillStyle=P.shirtShine; rr(ctx,cx-u*3.5,bodyY-u*6,u*7,u*2.5,u*2); ctx.fill();
    ctx.strokeStyle='rgba(255,255,255,0.1)'; ctx.lineWidth=u*0.6;
    ctx.beginPath(); ctx.moveTo(cx,bodyY-u*5.5); ctx.lineTo(cx,bodyY+u*2); ctx.stroke();

    // Arms
    const armSwing=(moving&&!this.reducedMotion)?legSwing*u*2.5:0;
    for (const [sign,swing] of [[-1,armSwing],[1,-armSwing]]) {
      ctx.fillStyle=P.shirt;
      rr(ctx,cx+sign*u*4,bodyY-u*5+swing,u*2.8,u*6,u*1.4); ctx.fill();
      ctx.fillStyle=P.skin;
      ctx.beginPath(); ctx.ellipse(cx+sign*u*5.4,bodyY+u*2+swing,u*1.8,u*2,0.2*sign,0,Math.PI*2); ctx.fill();
    }

    // Neck
    ctx.fillStyle=P.skinDark; rr(ctx,cx-u*1.4,bodyY-u*7.5,u*2.8,u*2,u*1.2); ctx.fill();

    // Head
    const hg=radGrad(ctx,cx-u*0.8,bodyY-u*12,u*5,P.skin,P.skinDark);
    ctx.fillStyle=hg;
    ctx.beginPath(); ctx.ellipse(cx,bodyY-u*11.5,u*4.2,u*4.8,0,0,Math.PI*2); ctx.fill();
    ctx.fillStyle=P.skinShade;
    ctx.beginPath(); ctx.ellipse(cx,bodyY-u*9.5,u*3.5,u*1.8,0,0,Math.PI); ctx.fill();

    // Hair
    ctx.fillStyle=P.hair;
    ctx.beginPath(); ctx.ellipse(cx,bodyY-u*14.2,u*4.2,u*2.2,0,Math.PI,Math.PI*2); ctx.fill();
    ctx.beginPath(); ctx.ellipse(cx-u*4,bodyY-u*12,u*1.2,u*2.5,0.3,0,Math.PI*2); ctx.fill();
    ctx.beginPath(); ctx.ellipse(cx+u*4,bodyY-u*12,u*1.2,u*2.5,-0.3,0,Math.PI*2); ctx.fill();
    ctx.fillStyle=P.hairShine;
    ctx.beginPath(); ctx.ellipse(cx-u*1,bodyY-u*14,u*1.8,u*1,-0.3,0,Math.PI*2); ctx.fill();

    // Eyes
    for (const [sx,brow] of [[-1.8,-0.15],[1.8,0.15]]) {
      const ex=cx+u*sx, ey=bodyY-u*12;
      ctx.fillStyle=P.eyeWhite; ctx.beginPath(); ctx.ellipse(ex,ey,u*1.5,u*1.1,brow*0.2,0,Math.PI*2); ctx.fill();
      ctx.fillStyle='#4878c8'; ctx.beginPath(); ctx.ellipse(ex+u*0.1,ey,u*0.9,u*1.0,0,0,Math.PI*2); ctx.fill();
      ctx.fillStyle=P.eye; ctx.beginPath(); ctx.ellipse(ex+u*0.15,ey,u*0.55,u*0.6,0,0,Math.PI*2); ctx.fill();
