294 | function tick(dt) {
295 |   let moving = false;
296 |   const before = { ...state.founder };
297 |   if (keys.size) {
298 |     const sx = Number(keys.has('d') || keys.has('arrowright')) - Number(keys.has('a') || keys.has('arrowleft'));
299 |     const sy = Number(keys.has('s') || keys.has('arrowdown')) - Number(keys.has('w') || keys.has('arrowup'));
300 |     const dx = sx + sy, dy = sy - sx;
301 |     const length = Math.hypot(dx, dy);
302 |     if (length) {
303 |       direction = { x: dx / length, y: dy / length };
304 |       const candidate = { x: state.founder.x + direction.x * speed * dt, y: state.founder.y + direction.y * speed * dt };
305 |       if (canTravel(state.founder, candidate)) state.founder = candidate;
306 |       else {
307 |         const xOnly = { x: candidate.x, y: state.founder.y };
308 |         const yOnly = { x: state.founder.x, y: candidate.y };
309 |         if(canTravel(state.founder,xOnly))state.founder=xOnly;
310 |         else if(canTravel(state.founder,yOnly))state.founder=yOnly;
311 |       }
312 |     }
313 |   } else if (path.length) {
314 |     let remaining = speed * dt;
315 |     while (path.length && remaining > 0) {
316 |       const target = path[0];
317 |       const dx = target.x - state.founder.x, dy = target.y - state.founder.y;
318 |       const distance = Math.hypot(dx, dy);
319 |       if (distance > .001) direction = { x: dx / distance, y: dy / distance };
320 |       if (distance <= remaining) { state.founder = { ...target };remaining -= distance;path.shift(); }
321 |       else { state.founder.x += direction.x * remaining;state.founder.y += direction.y * remaining;remaining = 0; }
322 |     }
323 |     if (!path.length) {
324 |       const object = pendingInteraction;pendingInteraction = null;save();updateUI();
325 |       if (object) openInteraction(object);
326 |     }
327 |   }
328 |   const distance = Math.hypot(state.founder.x - before.x, state.founder.y - before.y);
329 |   moving = distance > .00001;
330 |   state.distance += distance;
331 |   if (state.distance >= 1.2) complete('walk');
