 20 | export function project(x, y, z = 0) {
 21 |   return { x: x * TILE_SIZE, y: y * TILE_SIZE - z * TILE_SIZE * 0.5 };
 22 | }
 23 | 
 24 | export function unproject(x, y) {
 25 |   return { x: x / TILE_SIZE, y: y / TILE_SIZE };
 26 | }
