116 | export function parseSave(raw) {
117 |   const fresh = newState();
118 |   try {
119 |     const value = JSON.parse(raw);
120 |     if (!value || value.version !== 1) return fresh;
121 |     if (value.founder && isWalkable(value.founder.x, value.founder.y)) fresh.founder = { x: value.founder.x, y: value.founder.y };
122 |     if (Number.isFinite(value.energy)) fresh.energy = Math.max(0, Math.min(100, value.energy));
123 |     if (Number.isFinite(value.minutes)) fresh.minutes = Math.max(540, Math.min(1079, value.minutes));
124 |     if (Number.isFinite(value.distance)) fresh.distance = Math.max(0, Math.min(100000, value.distance));
125 |     if (Array.isArray(value.completed)) fresh.completed = TASKS.filter((id) => value.completed.includes(id));
126 |     fresh.sound = value.sound === true;
127 |     return fresh;
128 |   } catch { return fresh; }
129 | }

