299 |     const sy = Number(keys.has('s') || keys.has('arrowdown')) - Number(keys.has('w') || keys.has('arrowup'));
300 |     const dx = sx + sy, dy = sy - sx;
301 |     const length = Math.hypot(dx, dy);
302 |     if (length) {
303 |       direction = { x: dx / length, y: dy / length };
304 |       const candidate = { x: state.founder.x + direction.x * speed * dt, y: state.founder.y + direction.y * speed * dt };
305 |       if (canTravel(state.founder, candidate)) state.founder = candidate;
306 |       else {
307 |         const xOnly = { x: candidate.x, y: state.founder.y };
308 |         const yOnly = { x: state.founder.x, y: candidate.y };
