 44 | // A* on a quarter-tile grid, followed by collision-tested line-of-sight smoothing.
 45 | export function nearestWalkable(tx, ty, objects = OBJECTS) {
 46 |   if (isWalkable(tx, ty, objects)) return { x: tx, y: ty };
 47 |   // Spiral outward in quarter-tile steps until we find a walkable point
 48 |   const step = 0.25;
 49 |   for (let r = step; r <= 3; r += step) {
 50 |     let best = null, bestDist = Infinity;
 51 |     const n = Math.ceil((r * 2) / step);
 52 |     for (let i = 0; i <= n; i++) {
 53 |       const t = i / n;
 54 |       for (const [cx, cy] of [
 55 |         [tx - r + t * r * 2, ty - r],
 56 |         [tx + r, ty - r + t * r * 2],
 57 |         [tx + r - t * r * 2, ty + r],
 58 |         [tx - r, ty + r - t * r * 2],
 59 |       ]) {
 60 |         const rx = Math.round(cx / step) * step;
 61 |         const ry = Math.round(cy / step) * step;
 62 |         if (!isWalkable(rx, ry, objects)) continue;
 63 |         const d = Math.hypot(rx - tx, ry - ty);
 64 |         if (d < bestDist) { best = { x: rx, y: ry }; bestDist = d; }
 65 |       }
 66 |     }
 67 |     if (best) return best;
 68 |   }
 69 |   return null;
 70 | }
