import { OBJECTS, TASKS, SAVE_KEY, START, newState, parseSave, findPath, canTravel, isWalkable, nearestWalkable } from './world.js';
import { OfficeRenderer } from './renderer.js';

const $ = (selector) => document.querySelector(selector);
const canvas = $('#game');
const renderer = new OfficeRenderer(canvas);
let state = newState();
let storageAvailable = true;
try { state = parseSave(localStorage.getItem(SAVE_KEY)); } catch { storageAvailable = false; }
let path = [];
let pendingInteraction = null;
let paused = false;
let hovered = null;
let hoverFloor = null;
let direction = { x: 1, y: 0 };
let clockAccumulator = 0;
let saveAccumulator = 0;
let visualTime = 0;
let lastTime = 0;
let toastTimeout;
let audioContext;
let dialogAction = null;
let dialogKind = null;
const keys = new Set();
const dialog = $('#interaction-dialog');
const hoverLabel = $('#hover-label');
const speed = 2.65;

const interactions = {
