    description: 'A well-loved copy of The Lean Startup. A notebook full of crossed-out names. A book someone promised would change everything. There’s inspiration here, if you need it.',
    detail: 'A small reminder: progress beats perfection.', action: 'A little wiser already',
    perform(){toast('Build. Learn. Try again. You’ve got this.');},
  },
  ideas: {
