function save() {
  try {
    localStorage.setItem(SAVE_KEY, JSON.stringify(state));
    storageAvailable = true;
  } catch { storageAvailable = false; }
}

function updateUI() {
  const hour = Math.floor(state.minutes / 60);
  $('#clock').textContent = `${hour % 12 || 12}:${String(Math.floor(state.minutes % 60)).padStart(2, '0')} ${hour >= 12 ? 'PM' : 'AM'}`;
  const energy = Math.round(state.energy);
  $('#energy-value').textContent = String(energy);
  $('#energy-bar').setAttribute('aria-valuenow', String(energy));
  $('#energy-fill').style.width = `${state.energy}%`;
  $('#energy-fill').style.background = state.energy < 25 ? '#c85828' : '#58c858';
  for (const task of document.querySelectorAll('[data-task]')) {
    const completed = state.completed.includes(task.dataset.task);
    task.classList.toggle('complete', completed);
  }
  $('#founder-hint').style.opacity = state.distance > .2 ? '0' : '1';
  const soundButton = $('#sound-button');
  soundButton.setAttribute('aria-pressed', String(state.sound));
  soundButton.setAttribute('aria-label', `Turn sound ${state.sound ? 'off' : 'on'}`);
  soundButton.title = `Turn sound ${state.sound ? 'off' : 'on'}`;
}

function complete(id) {
  if (state.completed.includes(id)) return;
  state.completed.push(id);
  updateUI();
  save();
  if (id === 'walk') { toast('First steps, taken. Welcome to your little headquarters.'); playSound('complete'); }
}

function changeEnergy(amount) { state.energy = Math.max(0, Math.min(100, state.energy + amount)); }

function toast(message) {
  clearTimeout(toastTimeout);
  const element = $('#toast');
  element.textContent = message;
  element.hidden = false;
  toastTimeout = setTimeout(() => { element.hidden = true; }, 4500);
}

function playSound(kind = 'click') {
  if (!state.sound) return;
  try {
    audioContext ||= new (window.AudioContext || window.webkitAudioContext)();
    if (audioContext.state === 'suspended') void audioContext.resume().catch(() => {});
    const notes = kind === 'complete' ? [523.25, 659.25, 783.99] : kind === 'coffee' ? [392, 523.25] : [440];
    notes.forEach((frequency, i) => {
      const oscillator = audioContext.createOscillator();
      const gain = audioContext.createGain();
      const start = audioContext.currentTime + i * .1;
      oscillator.type = 'sine';oscillator.frequency.value = frequency;
      gain.gain.setValueAtTime(0, start);gain.gain.linearRampToValueAtTime(.035, start + .015);gain.gain.exponentialRampToValueAtTime(.001, start + .22);
      oscillator.connect(gain);gain.connect(audioContext.destination);oscillator.start(start);oscillator.stop(start + .23);
    });
  } catch { /* Sound is optional; unsupported or blocked audio never interrupts play. */ }
}

function goTo(destination, interaction = null) {
  if (paused) { toast('Resume the game to explore your office.'); return; }
  if (dialog.open) return;
  const nextPath = findPath(state.founder, destination);
  if (!nextPath) { toast('That spot is a little out of reach. Try a clear bit of floor.'); return; }
  keys.clear();
  path = nextPath;
  pendingInteraction = interaction;
  hoverLabel.hidden = true;
  updateUI();
  playSound();
}

function visit(id) {
  if (id === 'walk') {
    goTo({ x: 3.2, y: 7.8 });
    return;
  }
  const o = id === 'coffee' ? OBJECTS.find(o => o.id === 'cabinet') : OBJECTS.find(o => o.id === id);
  if (o) goTo(o.target, o);
}

function openInteraction(o) {
  const id = o.action || (o.type === 'plant' ? 'plant' : o.id);
  const config = interactions[id];
  if (!config) return;
  hoverLabel.hidden = true;
  keys.clear();
  dialogKind = id;
  $('#dialog-icon').innerHTML = config.icon === 'plant' ? '🌱' : `<svg><use href="#i-${config.icon}"/></svg>`;
  $('#dialog-eyebrow').textContent = config.eyebrow;
  $('#dialog-title').textContent = config.title;
  $('#dialog-description').textContent = config.description;
  $('#dialog-detail').textContent = config.detail;
  $('#dialog-action').textContent = config.action;
  $('#dialog-cancel').textContent = 'Maybe in a minute';
  dialogAction = () => {
    const wasComplete = state.completed.length === TASKS.length;
    config.perform();
    updateUI();save();
    if (!wasComplete && state.completed.length === TASKS.length) toast('Day one, done. Your startup story has officially begun. ✨');
  };
  dialog.showModal();
}

function setPaused(value) {
  paused = value;
  keys.clear();
  hoverLabel.hidden = true;
  $('#pause-overlay').hidden = !value;
  $('#pause-button').setAttribute('aria-pressed', String(value));
  $('#pause-button').setAttribute('aria-label', value ? 'Resume game' : 'Pause game');
  $('#pause-button').title = `${value ? 'Resume' : 'Pause'} (Space)`;
  updateUI();save();
  if (value) $('#resume-button').focus();
  else canvas.focus({ preventScroll: true });
}

function zoom(value) {
  renderer.zoom = Math.max(.8, Math.min(1.3, Math.round(value * 10) / 10));
  renderer.updateCamera();
  $('#zoom-reset').textContent = `${Math.round(renderer.zoom * 100)}%`;
  $('#zoom-out').disabled = renderer.zoom <= .8;
  $('#zoom-in').disabled = renderer.zoom >= 1.3;
  hoverLabel.hidden = true;
}

function pointerPosition(event) {
  const bounds = canvas.getBoundingClientRect();
  return { x: event.clientX - bounds.left, y: event.clientY - bounds.top };
}

canvas.addEventListener('pointermove', (event) => {
  if (paused || dialog.open || event.pointerType === 'touch') return;
  const p = pointerPosition(event);
  const object = renderer.hitTest(p.x, p.y);
  hovered = object?.id || null;
  hoverFloor = renderer.floorPoint(p.x, p.y);
  // Show crosshair on all floor tiles; pointer only over interactable objects
  const onFloor = hoverFloor.x >= 0 && hoverFloor.x <= 16 && hoverFloor.y >= 0 && hoverFloor.y <= 12;
  canvas.style.cursor = object ? 'pointer' : onFloor ? 'crosshair' : 'default';
  if (object) {
    hoverLabel.textContent = object.label;
    const small = document.createElement('small');small.textContent = 'Click to walk over';hoverLabel.append(small);
    hoverLabel.hidden = false;
    const half = hoverLabel.offsetWidth / 2 + 8;
    hoverLabel.style.left = `${Math.max(half, Math.min(renderer.width - half, p.x))}px`;
    hoverLabel.style.top = `${Math.max(65, p.y - 18)}px`;
  } else hoverLabel.hidden = true;
});
canvas.addEventListener('pointerleave', () => { hovered = null; hoverFloor = null; hoverLabel.hidden = true; });
canvas.addEventListener('click', (event) => {
  if (paused || dialog.open) return;
  canvas.focus({ preventScroll: true });
  const p = pointerPosition(event);
  const object = renderer.hitTest(p.x, p.y);
  if (object) { goTo(object.target, object); return; }
  const raw = renderer.floorPoint(p.x, p.y);
  const destination = nearestWalkable(raw.x, raw.y);
  if (destination) goTo(destination);
});

document.querySelectorAll('[data-destination]').forEach(button => button.addEventListener('click', () => visit(button.dataset.destination)));
document.querySelectorAll('[data-task]').forEach(button => button.addEventListener('click', () => visit(button.dataset.task)));
$('#zoom-in').addEventListener('click', () => zoom(renderer.zoom + .1));
$('#zoom-out').addEventListener('click', () => zoom(renderer.zoom - .1));
$('#zoom-reset').addEventListener('click', () => zoom(1));
$('#pause-button').addEventListener('click', () => setPaused(!paused));
$('#resume-button').addEventListener('click', () => setPaused(false));
$('#sound-button').addEventListener('click', () => { state.sound = !state.sound; updateUI(); save(); if (state.sound) { playSound('coffee'); toast('A little sound, now on.'); } else toast('Quiet mode. Just you and your ideas.'); });
$('#dialog-action').addEventListener('click', () => { const action = dialogAction; dialog.close(); action?.(); });
$('#dialog-close').addEventListener('click', () => dialog.close());
$('#dialog-cancel').addEventListener('click', () => dialog.close());
dialog.addEventListener('click', (event) => {
  const rect = dialog.getBoundingClientRect();
  if(event.target === dialog && (event.clientX < rect.left || event.clientX > rect.right || event.clientY < rect.top || event.clientY > rect.bottom)) dialog.close();
});
dialog.addEventListener('close', () => { dialogKind = null; dialogAction = null; updateUI(); canvas.focus({ preventScroll: true }); });
$('#reset-button').addEventListener('click', () => {
  keys.clear();
  dialogKind = 'reset';
  $('#dialog-icon').innerHTML = '<svg><use href="#i-reset"/></svg>';
  $('#dialog-eyebrow').textContent = 'A FRESH PAGE';
  $('#dialog-title').textContent = 'A new beginning?';
  $('#dialog-description').textContent = 'This will reset Alex, the clock, your energy, and the first-day checklist. Your current local save will be replaced.';
  $('#dialog-detail').textContent = 'Same little office. A brand-new day one.';
  $('#dialog-action').textContent = 'Start a fresh day';
  $('#dialog-cancel').textContent = 'Keep my current game';
  dialogAction = () => {
    state = newState();path = [];pendingInteraction = null;clockAccumulator = 0;saveAccumulator = 0;direction = { x: 1, y: 0 };
    setPaused(false);zoom(1);save();updateUI();toast('A fresh start. The possibilities are all yours.');
  };
  dialog.showModal();
});

const movementKeys = new Set(['w', 'a', 's', 'd', 'arrowup', 'arrowleft', 'arrowdown', 'arrowright']);
document.addEventListener('keydown', (event) => {
  if (event.altKey || event.ctrlKey || event.metaKey || /INPUT|TEXTAREA|SELECT/.test(event.target.tagName) || event.target.isContentEditable) return;
  const key = event.key.toLowerCase();
  if (dialog.open) return;
  if (key === ' ' && !event.repeat && event.target.tagName !== 'BUTTON') { event.preventDefault();setPaused(!paused);return; }
  if (key === 'escape') {
    if (paused) setPaused(false);
    else { path = [];pendingInteraction = null;keys.clear();updateUI(); }
  }
  if (!paused && movementKeys.has(key)) {
    event.preventDefault();keys.add(key);path = [];pendingInteraction = null;hoverLabel.hidden = true;
  }
});
document.addEventListener('keyup', (event) => keys.delete(event.key.toLowerCase()));
window.addEventListener('blur', () => { keys.clear();save(); });
window.addEventListener('pagehide', save);
document.addEventListener('visibilitychange', () => { keys.clear();lastTime = 0;if(document.hidden)save(); });
new ResizeObserver(() => { renderer.resize();hoverLabel.hidden = true; }).observe(canvas);

function tick(dt) {
  let moving = false;
  const before = { ...state.founder };
  if (keys.size) {
    const sx = Number(keys.has('d') || keys.has('arrowright')) - Number(keys.has('a') || keys.has('arrowleft'));
    const sy = Number(keys.has('s') || keys.has('arrowdown')) - Number(keys.has('w') || keys.has('arrowup'));
    const dx = sx + sy, dy = sy - sx;
    const length = Math.hypot(dx, dy);
    if (length) {
      direction = { x: dx / length, y: dy / length };
      const candidate = { x: state.founder.x + direction.x * speed * dt, y: state.founder.y + direction.y * speed * dt };
      if (canTravel(state.founder, candidate)) state.founder = candidate;
      else {
        const xOnly = { x: candidate.x, y: state.founder.y };
        const yOnly = { x: state.founder.x, y: candidate.y };
        if(canTravel(state.founder,xOnly))state.founder=xOnly;
        else if(canTravel(state.founder,yOnly))state.founder=yOnly;
      }
    }
  } else if (path.length) {
    let remaining = speed * dt;
    while (path.length && remaining > 0) {
      const target = path[0];
      const dx = target.x - state.founder.x, dy = target.y - state.founder.y;
      const distance = Math.hypot(dx, dy);
      if (distance > .001) direction = { x: dx / distance, y: dy / distance };
      if (distance <= remaining) { state.founder = { ...target };remaining -= distance;path.shift(); }
      else { state.founder.x += direction.x * remaining;state.founder.y += direction.y * remaining;remaining = 0; }
    }
    if (!path.length) {
      const object = pendingInteraction;pendingInteraction = null;save();updateUI();
      if (object) openInteraction(object);
    }
  }
  const distance = Math.hypot(state.founder.x - before.x, state.founder.y - before.y);
  moving = distance > .00001;
  state.distance += distance;
  if (state.distance >= 1.2) complete('walk');
  if (moving) $('#founder-hint').style.opacity = '0';
  clockAccumulator += dt;
  saveAccumulator += dt;
  if (clockAccumulator >= 3) { state.minutes = Math.min(1079, state.minutes + 1);clockAccumulator %= 3;updateUI(); }
  if (saveAccumulator >= 2) { saveAccumulator %= 2;save(); }
  return moving;
}

function frame(time) {
  const dt = lastTime ? Math.min((time - lastTime) / 1000, .05) : 0;
  lastTime = time;
  let moving = false;
  if (!paused && !dialog.open && !document.hidden) { visualTime += dt * 1000; moving = tick(dt); }
  renderer.render({ founder: state.founder, path, hovered, hoverFloor, direction, moving, time: visualTime });
  requestAnimationFrame(frame);
}

