function changeEnergy(amount) { state.energy = Math.max(0, Math.min(100, state.energy + amount)); }

function advanceDay() {
  if (state.day >= 10) {
    // Win!
    toast('🚀 LAUNCHED! v1.0 is live. You built a startup in ten days. The journey starts now. ✨');
    playSound('complete');
    showDayEnd(true);
    return;
  }
  const completedDay = state.day;
  state.day += 1;
  state.completed = [];
  state.energy = Math.min(100, state.energy + 30); // overnight recovery
  state.minutes = 540; // reset to 9 AM
  state.distance = 0;
  state.founder = { ...START };
  save();
  updateUI();
  showDayEnd(false, completedDay);
}

function showDayEnd(isWin, completedDay = 0) {
  const overlay = $('#day-end-overlay');
  const title = $('#day-end-title');
  const body = $('#day-end-body');
  const btn = $('#day-end-btn');
  const progress = $('#day-end-progress');

  if (isWin) {
    title.textContent = '🚀 You shipped it.';
    body.textContent = 'Ten days. One product. Countless cups of coffee. v1.0 is live in the world. Whatever comes next, you\'ll figure it out — you always do.';
    btn.textContent = 'Play again';
    progress.textContent = 'LAUNCHED · DAY 10 COMPLETE';
  } else {
    const d = DAY_PROGRESS[state.day - 1]; // next day
    const msgs = [
      'Prototype logged. Sleep. Try again tomorrow.',
      'Day two in the books. It\'s getting real.',
      'Feedback absorbed. You\'re better for it.',
      'Core flow polished. Four days down.',
      'Halfway to launch. The demo lives.',
      'Paid features built. This is a business.',
      'Rough edges gone. Product shape achieved.',
      'Launch prep done. Two days left.',
      'Final polish shipped. Tomorrow you launch.',
    ];
    title.textContent = `Day ${completedDay} complete.`;
    body.textContent = msgs[completedDay - 1] || 'Another day done. Keep going.';
    btn.textContent = `Start Day ${state.day}`;
    // Progress bar fill
    progress.textContent = `DAY ${completedDay} / 10 COMPLETE`;
    progress.style.setProperty('--day-pct', `${(completedDay / 10) * 100}%`);
  }

  overlay.hidden = false;
  btn.focus();

  btn.onclick = () => {
    overlay.hidden = true;
    if (isWin) {
      // Full reset
      const s = newState(); s.sound = state.sound;
      Object.assign(state, s);
      save(); updateUI();
    }
    canvas.focus({ preventScroll: true });
  };
}

